/* Contenido de «Portugués básico A1 (Brasil)». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-portugues-a1",{"l":{"c-portugues-a1-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar:</b> este es un <b>curso libre de capacitación</b> con constancia de Instituto Mara. Trabaja las habilidades del nivel <b>A1 del Marco Común Europeo (MCER)</b>: el de quien empieza y ya puede presentarse, dar sus datos y resolver situaciones sencillas de la vida diaria. <b>No es una certificación oficial de portugués</b> como el <b>CELPE-Bras</b> (el examen oficial del gobierno de Brasil), ni tiene validez oficial ante la SEP. Si una universidad, una empresa o un trámite migratorio te pide un nivel certificado, tendrás que presentar ese examen por tu cuenta en un centro aplicador autorizado."},{"tipo":"texto","texto":"Buena noticia: si hablas español, ya entiendes por escrito buena parte del portugués. <i>Eu trabalho em um hotel</i> se entiende casi solo. Lo difícil es <b>escucharlo y pronunciarlo</b>, y cuidarte de las palabras que se parecen pero significan otra cosa. En este curso vas a aprender el portugués de <b>Brasil</b>, el que más vas a oír con turistas en Cancún, en empresas brasileñas en México y en series y música.<br><br><b>Cómo leer la pronunciación aproximada</b> que verás en todo el curso: <b>ã, õ, ẽ, ĩ, ũ</b> = vocales nasales (el aire sale también por la nariz); <b>j</b> = una j suave, como aspirada (así suena la r inicial: <i>Rio</i> = jíu); <b>y</b> = la j y la g portuguesas, como la «y» de un argentino en «yo»; <b>sh</b> = como cuando pides silencio; <b>z</b> = una s que zumba, como abeja; <b>ch</b> y <b>dj</b> = como en «chile» y en «adjetivo». La sílaba con acento escrito es la que suena más fuerte."},{"tipo":"tabla","titulo":"Saludos y despedidas","voz":true,"colVoz":0,"encabezados":["Portugués","Se lee aprox.","Español","Cuándo"],"filas":[["Oi!","ói","¡Hola!","Lo más común, con casi todos"],["Olá!","olá","¡Hola!","Un poco más formal; muy usado por escrito"],["Bom dia!","bõ djía","Buenos días","Hasta el mediodía"],["Boa tarde!","bóa tárdji","Buenas tardes","Del mediodía hasta que oscurece"],["Boa noite!","bóa nóichi","Buenas noches","En la noche, al llegar y al irte"],["Tchau!","cháu","¡Adiós! / ¡Bye!","Informal, pero se usa con todos"],["Até logo!","até lógu","Hasta luego","Siempre funciona"],["Até amanhã!","até amañã","Hasta mañana","Si se ven al día siguiente"],["Obrigado!","obrigádu","¡Gracias!","Lo dice un hombre"],["Obrigada!","obrigáda","¡Gracias!","Lo dice una mujer"],["De nada.","dji náda","De nada.","Para responder a las gracias"],["Por favor.","pur favór","Por favor.","Al pedir algo"]],"nota":"<b>Obrigado</b> significa literalmente «obligado» (me siento obligado contigo), por eso <b>cambia según quien habla</b>, no según a quién se lo dices: una mujer siempre dice <i>obrigada</i>."},{"tipo":"comparar","titulo":"Calcos del español al saludar","malTitulo":"Evita","mal":"<i>Bons dias!</i> (en plural, como «buenos días»)<br><i>Gracias!</i> o <i>Graças!</i><br>Una mujer que dice <i>Obrigado</i>.","bienTitulo":"Correcto","bien":"<i><b>Bom dia! Boa tarde! Boa noite!</b></i> siempre en singular.<br><i><b>Obrigado</b></i> (hombre) · <i><b>Obrigada</b></i> (mujer). Más énfasis: <i>Muito obrigada!</i><br><i>Graças a Deus</i> sí existe, pero significa «gracias a Dios»."},{"tipo":"dialogo","titulo":"Diálogo — Recepción de un hotel en Cancún","lineas":[{"quien":"Karla","en":"Boa tarde, senhora! Bem-vinda a Cancún!","es":"¡Buenas tardes, señora! ¡Bienvenida a Cancún!"},{"quien":"Dona Beatriz","en":"Boa tarde! Muito obrigada.","es":"¡Buenas tardes! Muchas gracias."},{"quien":"Karla","en":"Tudo bem com a senhora?","es":"¿Cómo está usted?"},{"quien":"Dona Beatriz","en":"Tudo ótimo, obrigada. E você?","es":"Muy bien, gracias. ¿Y tú?"},{"quien":"Karla","en":"Tudo bem, obrigada. Aqui está a sua chave: quarto 204.","es":"Bien, gracias. Aquí está su llave: habitación 204."},{"quien":"Dona Beatriz","en":"Obrigada! Até logo.","es":"¡Gracias! Hasta luego."},{"quien":"Karla","en":"De nada. Até logo e boa estadia!","es":"De nada. ¡Hasta luego y que disfrute su estancia!"}]},{"tipo":"practica","rotulo":"¿Qué dices?","preguntas":[{"p":"Son las 9 de la mañana y llega un huésped brasileño. Dices…","ops":["Boa tarde!","Bom dia!","Bons dias!"],"correcta":1,"explica":"Hasta el mediodía, <b>Bom dia</b>, en singular."},{"p":"Eres mujer y te acaban de ayudar. Dices…","ops":["Obrigado!","Obrigada!","Gracias!"],"correcta":1,"explica":"<i>Obrigado/obrigada</i> cambia según <b>quien habla</b>."},{"p":"Te despides de un compañero que ves todos los días.","ops":["Até amanhã!","Bom dia!","De nada!"],"correcta":0},{"p":"Son las 8 de la noche y te vas del restaurante. Dices…","ops":["Boa tarde!","Boa noite!","Bom dia!"],"correcta":1,"explica":"<b>Boa noite</b> sirve para llegar y para irte en la noche."},{"p":"Alguien te dice <i>Obrigado!</i> Contestas…","ops":["Por favor.","De nada.","Tchau, obrigado."],"correcta":1,"explica":"También se oye <i>Por nada</i> o, muy brasileño, <i>Imagina!</i>"}]},{"tipo":"relacionar","rotulo":"Relaciona cada fórmula con su significado","voz":true,"pares":[["Até logo","Hasta luego"],["Até amanhã","Hasta mañana"],["Bem-vinda","Bienvenida"],["Muito obrigado","Muchas gracias"],["De nada","De nada"],["Boa tarde","Buenas tardes"]]},{"tipo":"pronunciar","rotulo":"Dilo en voz alta","frases":[{"en":"Bom dia, senhora!","pron":"bõ djía siñóra","es":"¡Buenos días, señora!"},{"en":"Boa noite, senhor.","pron":"bóa nóichi siñór","es":"Buenas noches, señor."},{"en":"Muito obrigado!","pron":"mũintu obrigádu","es":"¡Muchas gracias! (hombre)"},{"en":"Muito obrigada!","pron":"mũintu obrigáda","es":"¡Muchas gracias! (mujer)"},{"en":"Tchau, até amanhã!","pron":"cháu, até amañã","es":"¡Adiós, hasta mañana!"}]},{"tipo":"clave","items":["<b>Bom dia</b>, <b>boa tarde</b>, <b>boa noite</b>: siempre en singular.","<b>Oi</b> es el «hola» de todos los días; <b>tchau</b> y <b>até logo</b> para despedirte.","Hombre: <b>obrigado</b> · mujer: <b>obrigada</b>.","Este curso es libre, con constancia de Instituto Mara; no sustituye el CELPE-Bras."]}],"c-portugues-a1-m1-l2":[{"tipo":"texto","texto":"En casi todo Brasil, «tú» se dice <b>você</b>, y se conjuga igual que «él» o «ella»: <i>você é</i> (tú eres), <i>você fala</i> (tú hablas). Eso te simplifica la vida: una forma menos que aprender. Para hablar de usted, con clientes mayores, jefes o personas de respeto, se usa <b>o senhor</b> (a un hombre) y <b>a senhora</b> (a una mujer), también con el verbo de «él/ella»: <i>O senhor é daqui?</i> (¿Usted es de aquí?). «Ustedes» es <b>vocês</b>.<br><br>Oirás <b>tu</b> en el sur y en partes del nordeste, muchas veces con el mismo verbo que <i>você</i> (<i>tu vai?</i>). Tú usa <i>você</i> y no te equivocas. Detalle cultural: con una señora a la que quieres mostrar respeto y cariño, se usa <b>dona</b> + su nombre: <i>dona Helena</i>."},{"tipo":"tabla","titulo":"Las mismas preguntas, dos registros","voz":true,"colVoz":0,"encabezados":["Portugués","Registro","Español"],"filas":[["Tudo bem?","informal","¿Qué tal? / ¿Todo bien?"],["Tudo bem, e você?","informal","Bien, ¿y tú?"],["Tudo bom?","informal","¿Qué tal? (variante)"],["E aí, beleza?","muy informal","¿Qué onda?"],["Como vai o senhor?","formal","¿Cómo está usted? (a un hombre)"],["Como vai a senhora?","formal","¿Cómo está usted? (a una mujer)"],["Muito bem, obrigado. E o senhor?","formal","Muy bien, gracias. ¿Y usted?"],["Com licença.","los dos","Con permiso."],["Desculpa!","informal","¡Perdón!"],["Desculpe.","formal","Disculpe."]],"nota":"<i>Tudo bem?</i> es comodín: sirve para preguntar y para contestar. <i>Tudo bem? — Tudo bem!</i> Se contesta <i>Tudo</i> o <i>Tudo ótimo</i>, casi nunca con un problema."},{"tipo":"comparar","titulo":"«Usted» no existe en portugués","malTitulo":"Evita","mal":"<i>Usted é brasileiro?</i><br><i>O senhor, você é daqui?</i> (mezclar los dos tratos)<br><i>Vocês sois de São Paulo?</i>","bienTitulo":"Correcto","bien":"<i><b>O senhor</b> é brasileiro?</i><br><i><b>A senhora</b> é daqui?</i> (y sigue con <i>a senhora</i> toda la plática)<br><i><b>Vocês são</b> de São Paulo?</i>"},{"tipo":"dialogo","titulo":"Diálogo — Oficina de una empresa brasileña en Querétaro","lineas":[{"quien":"Rafael","en":"Oi, Diego! Tudo bem?","es":"¡Hola, Diego! ¿Qué tal?"},{"quien":"Diego","en":"Tudo, e você?","es":"Bien, ¿y tú?"},{"quien":"Rafael","en":"Tudo ótimo. Diego, esta é a dona Helena, a diretora.","es":"Muy bien. Diego, ella es la señora Helena, la directora."},{"quien":"Diego","en":"Muito prazer, dona Helena. Como vai a senhora?","es":"Mucho gusto, señora Helena. ¿Cómo está usted?"},{"quien":"Dona Helena","en":"Muito bem, obrigada. Pode me chamar de você, viu?","es":"Muy bien, gracias. Puedes hablarme de tú, ¿eh?"},{"quien":"Diego","en":"Tá bom! Seja bem-vinda a Querétaro, Helena.","es":"¡Está bien! Bienvenida a Querétaro, Helena."}]},{"tipo":"practica","rotulo":"¿Você o o senhor / a senhora?","preguntas":[{"p":"Hablas con un compañero de tu edad.","ops":["Vossa Senhoria","você","vós","o senhor"],"correcta":1,"explica":"Con compañeros de tu edad en Brasil usas <b>você</b>; <i>vós</i> casi no se usa y <i>Vossa Senhoria</i> es para documentos muy formales."},{"p":"Atiendes a una clienta de 70 años en el hotel.","ops":["o senhor","tu","a senhora","você"],"correcta":2,"explica":"Con personas mayores o clientes que quieres tratar con respeto: <b>a senhora</b>, en femenino porque es mujer."},{"p":"Hablas con dos amigos a la vez.","ops":["você","vocês","os senhores"],"correcta":1},{"p":"<i>O senhor ___ daqui?</i>","ops":["é","és","sois"],"correcta":0,"explica":"<i>O senhor</i> y <i>você</i> usan el verbo de «él»: <b>é</b>."},{"p":"Te preguntan <i>Tudo bem?</i> Lo más natural es…","ops":["Tudo, e você?","Sim, obrigado.","Estou bem, e o senhor tudo?"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa el saludo","voz":true,"items":[{"frase":"Oi, Ana! Tudo ___?","resp":["bem","bom"],"es":"¡Hola, Ana! ¿Qué tal?"},{"frase":"Como ___ a senhora?","resp":["vai"],"es":"¿Cómo está usted?"},{"frase":"Muito ___, dona Helena.","resp":["prazer"],"es":"Mucho gusto, señora Helena."},{"frase":"Tudo ótimo, e ___?","resp":["você","voce"],"es":"Muy bien, ¿y tú?"},{"frase":"Com ___, senhor.","resp":["licença","licenca"],"es":"Con permiso, señor."}]},{"tipo":"escuchar","rotulo":"Escucha y repite","frases":[{"en":"E aí, tudo bem?","pron":"i aí, túdu bẽi","es":"¿Qué onda, todo bien?"},{"en":"Tudo ótimo, e você?","pron":"túdu óchimu, i vosê","es":"Muy bien, ¿y tú?"},{"en":"Como vai a senhora?","pron":"kómu vai a siñóra","es":"¿Cómo está usted?"},{"en":"Com licença.","pron":"kõ lisẽsa","es":"Con permiso."},{"en":"Desculpe, senhor.","pron":"djiskúupi, siñór","es":"Disculpe, señor."}]},{"tipo":"clave","items":["<b>você</b> = tú, con el verbo de «él»: <i>você é, você fala</i>.","<b>o senhor / a senhora</b> = usted; <b>vocês</b> = ustedes.","<i>Tudo bem? — Tudo, e você?</i> es el saludo de todos los días.","<b>Com licença</b> para pedir paso; <b>desculpa/desculpe</b> para disculparte."]}],"c-portugues-a1-m1-l3":[{"tipo":"texto","texto":"Con cuatro frases ya te puedes presentar: <b>Meu nome é…</b> o <b>Eu me chamo…</b> (me llamo), <b>Sou…</b> (soy), <b>Moro em…</b> (vivo en) y <b>Trabalho…</b> (trabajo). Fíjate en tres detalles: <b>1)</b> para decir dónde vives, en Brasil se usa <b>morar</b>, no <i>viver</i>. <b>2)</b> «Mucho gusto» es <b>Muito prazer</b> (o solo <i>Prazer!</i>). <b>3)</b> Los brasileños suelen poner artículo antes de los nombres de personas conocidas: <i>a Camila, o Paulo</i>. Y para responder «sí», muchas veces repiten el verbo: <i>Você é daqui? — <b>Sou</b>, sim!</i>"},{"tipo":"tabla","titulo":"Frases para presentarte","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Meu nome é Laura.","Me llamo Laura."],["Eu me chamo Diego.","Me llamo Diego."],["Sou mexicano.","Soy mexicano."],["Sou mexicana.","Soy mexicana."],["Sou de Puebla.","Soy de Puebla."],["Moro em Mérida.","Vivo en Mérida."],["Trabalho em um hotel.","Trabajo en un hotel."],["Qual é o seu nome?","¿Cómo te llamas?"],["De onde você é?","¿De dónde eres?"],["Onde você mora?","¿Dónde vives?"],["Muito prazer!","¡Mucho gusto!"],["O prazer é meu.","El gusto es mío."]],"nota":"En la conversación, <i>em um</i> casi siempre se junta: <i>Trabalho <b>num</b> hotel</i>. Las dos formas son correctas."},{"tipo":"comparar","titulo":"Calcos que delatan al hispanohablante","malTitulo":"Evita","mal":"<i>Muito gosto!</i><br><i>Vivo em Mérida.</i> (se entiende, pero no es lo que dice un brasileño)<br><i>Me chamo é Laura.</i>","bienTitulo":"Correcto","bien":"<i><b>Muito prazer!</b></i> (<i>gosto</i> es sabor o gusto por algo)<br><i><b>Moro</b> em Mérida.</i><br><i><b>Meu nome é</b> Laura.</i> o <i><b>Eu me chamo</b> Laura.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Recorrido turístico en Oaxaca","lineas":[{"quien":"Rodrigo","en":"Bom dia, pessoal! Meu nome é Rodrigo e eu sou o guia de vocês hoje.","es":"¡Buenos días a todos! Me llamo Rodrigo y hoy soy su guía."},{"quien":"Camila","en":"Bom dia, Rodrigo! Eu sou a Camila, e este é o meu marido, o Paulo.","es":"¡Buenos días, Rodrigo! Yo soy Camila, y este es mi esposo, Paulo."},{"quien":"Paulo","en":"Muito prazer!","es":"¡Mucho gusto!"},{"quien":"Rodrigo","en":"O prazer é meu! De onde vocês são?","es":"¡El gusto es mío! ¿De dónde son?"},{"quien":"Camila","en":"Somos brasileiros, de Belo Horizonte. E você, é daqui?","es":"Somos brasileños, de Belo Horizonte. ¿Y tú eres de aquí?"},{"quien":"Rodrigo","en":"Sou, sim! Sou de Oaxaca, mas moro na Cidade do México.","es":"¡Sí! Soy de Oaxaca, pero vivo en la Ciudad de México."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Mucho gusto» se dice…","ops":["Muito gosto!","Muito prazer!","Muito bem!"],"correcta":1},{"p":"«Vivo en Guadalajara» (lo más natural en Brasil)","ops":["Vivo em Guadalajara.","Moro em Guadalajara.","Moro a Guadalajara."],"correcta":1,"explica":"Para tu casa o tu ciudad, <b>morar</b>."},{"p":"Una mujer de Monterrey dice: <i>Sou…</i>","ops":["mexicano","mexicana","mexicanos"],"correcta":1},{"p":"Te preguntan <i>Você é daqui?</i> y sí eres de ahí. Respuesta muy brasileña:","ops":["Sou, sim!","Sim, eu estou.","Sou daqui não."],"correcta":0,"explica":"En Brasil se contesta repitiendo el verbo: <b>Sou</b>, <b>Moro</b>, <b>Trabalho</b>…"},{"p":"«¿Dónde vives?»","ops":["Onde você mora?","Onde você é?","De onde você vive?"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma la presentación","voz":true,"items":[{"frase":"Meu nome é Ana e sou mexicana","es":"Me llamo Ana y soy mexicana"},{"frase":"Moro em Monterrey com a minha família","es":"Vivo en Monterrey con mi familia"},{"frase":"Trabalho num hotel em Cancún","es":"Trabajo en un hotel en Cancún"},{"frase":"De onde você é?","es":"¿De dónde eres?"}]},{"tipo":"pronunciar","rotulo":"Preséntate en voz alta","frases":[{"en":"Meu nome é Diego.","pron":"méu nõmi é djiégu","es":"Me llamo Diego."},{"en":"Sou mexicano, de Puebla.","pron":"sôu meshikãnu, dji pwébla","es":"Soy mexicano, de Puebla."},{"en":"Moro na Cidade do México.","pron":"móru na sidádji du méshiku","es":"Vivo en la Ciudad de México."},{"en":"Trabalho num hotel.","pron":"trabáliu nũ otéu","es":"Trabajo en un hotel."},{"en":"Muito prazer!","pron":"mũintu prazér","es":"¡Mucho gusto!"}]},{"tipo":"reflexion","rotulo":"Tu presentación","pregunta":"Escribe tu presentación en cuatro frases: tu nombre, tu nacionalidad, la ciudad donde vives y dónde trabajas o estudias. Luego dila en voz alta tres veces, sin leer, cuidando la o final que suena u (<i>mexicano</i> = meshikãnu).","ayuda":"Oi! Meu nome é… Sou mexicano / mexicana. Moro em… Trabalho num / numa… / Sou estudante."},{"tipo":"clave","items":["<i>Meu nome é… / Eu me chamo…, sou…, moro em…, trabalho…</i>","«Mucho gusto» = <b>Muito prazer</b>; «vivir en» = <b>morar em</b>.","Para decir «sí», repite el verbo: <i>Você mora aqui? — <b>Moro</b>, sim.</i>","Los brasileños ponen artículo antes de nombres: <i>a Camila, o Paulo</i>."]}],"c-portugues-a1-m1-l4":[{"tipo":"texto","texto":"Aquí el español te da ventaja: <b>ser</b> y <b>estar</b> se reparten el trabajo casi igual que en nuestro idioma. <i>Sou engenheira</i> (soy), <i>Estou cansada</i> (estoy). Solo cambian las formas y tres usos: <b>1)</b> «tener hambre, sed, frío, calor, sueño, prisa» se dice casi siempre con <b>estar com</b>: <i>Estou com fome</i>. <b>2)</b> Para lugares que no se mueven (un banco, una calle, una ciudad) se usa mucho <b>ficar</b>: <i>Onde fica o banco?</i> (¿Dónde está el banco?). <b>3)</b> En Brasil el pronombre se dice más que en español, porque <i>você</i>, <i>ele</i> y <i>ela</i> comparten la misma forma del verbo."},{"tipo":"tabla","titulo":"Ser en presente","voz":true,"colVoz":0,"encabezados":["Portugués","Se lee aprox.","Español"],"filas":[["eu sou","éu sôu","yo soy"],["você é","vosê é","tú eres"],["ele é / ela é","éli é / éla é","él es / ella es"],["a gente é","a yẽchi é","nosotros somos (informal)"],["nós somos","nós sômus","nosotros somos"],["vocês são","vosês sãu","ustedes son"],["eles são / elas são","élis sãu / élas sãu","ellos son / ellas son"]],"nota":"<b>a gente</b> (literalmente «la gente») es la forma más común de decir «nosotros» en la conversación, y se conjuga como «él»: <i>A gente é de Puebla.</i>"},{"tipo":"tabla","titulo":"Estar en presente","voz":true,"colVoz":0,"encabezados":["Portugués","Se lee aprox.","Español"],"filas":[["eu estou","éu istôu","yo estoy"],["você está","vosê istá","tú estás"],["ele está / ela está","éli istá / éla istá","él está / ella está"],["nós estamos","nós istãmus","nosotros estamos"],["vocês estão","vosês istãu","ustedes están"],["eles estão / elas estão","élis istãu / élas istãu","ellos están / ellas están"]],"nota":"En la plática, <i>estar</i> se acorta muchísimo: <i>tô</i> (estoy), <i>tá</i> (está), <i>tão</i> (están). <i>Tô cansado. Tá bom!</i> Vas a oírlo en todos lados."},{"tipo":"comparar","titulo":"Tener hambre = estar com fome","malTitulo":"Suena menos natural","mal":"<i>Tenho fome.</i><br><i>Tenho frio.</i><br><i>Tenho pressa.</i>","bienTitulo":"Lo que dice un brasileño","bien":"<i><b>Estou com</b> fome.</i> (hambre)<br><i><b>Estou com</b> frio.</i> (frío)<br><i><b>Estou com</b> pressa.</i> (prisa)<br>También: <i>com sede</i> (sed), <i>com calor</i>, <i>com sono</i> (sueño)."},{"tipo":"escuchar","rotulo":"Escucha frases con ser y estar","frases":[{"en":"Eu sou engenheira.","pron":"éu sôu ẽyeñéira","es":"Soy ingeniera."},{"en":"Ela é muito simpática.","pron":"éla é mũintu simpáchika","es":"Ella es muy amable."},{"en":"A gente é de Guadalajara.","es":"Somos de Guadalajara."},{"en":"Vocês estão cansados?","pron":"vosês istãu kãsádus","es":"¿Están cansados?"},{"en":"Estou com fome!","pron":"istôu kõ fõmi","es":"¡Tengo hambre!"},{"en":"Onde fica o banco?","pron":"õdji fíka u bãku","es":"¿Dónde está el banco?"}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"Nós ___ mexicanos.","ops":["são","somos","estamos"],"correcta":1},{"p":"A senhora ___ cansada?","ops":["está","estás","estou"],"correcta":0,"explica":"<i>a senhora</i> usa el verbo de «ella»: <b>está</b>."},{"p":"Marina e Júlia ___ de Recife.","ops":["é","são","somos"],"correcta":1},{"p":"«Tengo sed» en Brasil se dice…","ops":["Estou com sede.","Sou com sede.","Tenho de sede."],"correcta":0},{"p":"<i>A gente ___ amigos.</i>","ops":["somos","é","são"],"correcta":1,"explica":"<b>a gente</b> se conjuga como «él»: <i>a gente é</i>."}]},{"tipo":"completar","rotulo":"Completa con ser o estar","voz":true,"items":[{"frase":"Nós ___ de Monterrey.","resp":["somos"],"es":"Somos de Monterrey."},{"frase":"Você ___ brasileiro?","resp":["é"],"es":"¿Eres brasileño?"},{"frase":"Eu ___ com pressa.","resp":["estou","tô"],"es":"Tengo prisa."},{"frase":"Eles ___ no escritório.","resp":["estão"],"es":"Están en la oficina."},{"frase":"Onde ___ o hotel?","resp":["fica","está"],"es":"¿Dónde está el hotel?"}]},{"tipo":"tarjetas","rotulo":"Memoriza ser y estar","voz":true,"vozEn":"reverso","instruccion":"Ves la forma en español; di la forma en portugués antes de voltear.","tarjetas":[{"frente":"yo soy","reverso":"eu sou","ej":"Eu sou de Puebla."},{"frente":"ustedes son","reverso":"vocês são","ej":"Vocês são brasileiros?"},{"frente":"yo estoy","reverso":"eu estou","ej":"Eu estou cansado."},{"frente":"ellos están","reverso":"eles estão","ej":"Eles estão no hotel."},{"frente":"tengo hambre","reverso":"estou com fome","ej":"Estou com muita fome!"},{"frente":"nosotros somos (informal)","reverso":"a gente é","ej":"A gente é colega de trabalho."}]},{"tipo":"clave","items":["<b>ser</b>: <i>sou, é, somos, são</i> · <b>estar</b>: <i>estou, está, estamos, estão</i>.","Hambre, sed, frío, prisa: <b>estar com</b> (<i>Estou com fome</i>).","Lugares fijos: <i>Onde <b>fica</b>…?</i>","<b>a gente</b> = nosotros, con el verbo de «él»."]}],"c-portugues-a1-m1-l5":[{"tipo":"texto","texto":"Por escrito, el portugués se parece mucho al español; hablado, suena muy distinto. Los brasileños entienden bien a un mexicano, pero si pronuncias «a la española» te van a contestar en español o no te van a entender a la primera. Estas son las claves, de la más importante a la menos: <b>1)</b> la <b>o</b> y la <b>e</b> finales sin acento se relajan y suenan casi <b>u</b> e <b>i</b>; <b>2)</b> <b>t</b> y <b>d</b> antes de sonido «i» suenan <b>chi</b> y <b>dji</b>; <b>3)</b> las <b>vocales nasales</b>; <b>4)</b> la <b>r inicial</b> y la <b>rr</b> suenan como una j suave. En Portugal y en algunas regiones de Brasil cambian algunos de estos sonidos; aquí aprendes el más extendido."},{"tipo":"tabla","titulo":"Los sonidos clave","voz":true,"colVoz":1,"encabezados":["Se escribe","Ejemplos","Cómo suena"],"filas":[["o / e finales","obrigado, leite, gente","La o final suena u y la e final suena i: obrigádu, léichi, yẽchi."],["ti / di · te / de finales","noite, dia, cidade","chi y dji: nóichi, djía, sidádji."],["ão","pão, não, São Paulo","«au» nasal (ãu): el aire sale por la nariz; nunca «ao»."],["ões / ãe","lições, mãe, pães","«õis» y «ãi» nasales: lisõis, mãi."],["m / n al final de sílaba","bom, sim, um","No cierras con m ni n: la vocal se vuelve nasal (bõ, sĩ, ũ)."],["ç","açaí, almoço, praça","Siempre como s: asaí, almósu."],["lh","trabalho, filho, olho","Como «li» rápido: trabáliu, fíliu."],["nh","amanhã, vinho, banheiro","Como nuestra ñ: amañã, víñu."],["r inicial / rr","Rio, rua, carro","Una j suave, aspirada: jíu, júa, káju."],["r entre vocales","caro, hora, obrigado","Como la r de «pero»: káru, óra."],["s entre vocales","casa, mesa, música","Una s que zumba: káza, méza."],["j / g + e, i","janeiro, gente, hoje","Como la «y» argentina: yanéiru, yẽchi, óyi."]],"nota":"La <b>l</b> al final de sílaba suena casi <b>u</b>: <i>Brasil</i> = brazíu, <i>hotel</i> = otéu, <i>Natal</i> = natáu."},{"tipo":"comparar","titulo":"Así suena un principiante… y así un brasileño","malTitulo":"Pronunciación a la española","mal":"<i>Rio</i> con r de «perro»<br><i>noite</i> como «noi-te»<br><i>obrigado</i> con o final clara<br><i>pão</i> como «pa-o»<br><i>Brasil</i> con l final","bienTitulo":"Pronunciación brasileña","bien":"<i>Rio</i> = <b>jíu</b><br><i>noite</i> = <b>nóichi</b><br><i>obrigado</i> = <b>obrigádu</b><br><i>pão</i> = <b>pãu</b> (nasal)<br><i>Brasil</i> = <b>brazíu</b>"},{"tipo":"escuchar","rotulo":"Escucha palabras con los sonidos clave","frases":[{"en":"São Paulo","pron":"sãu páulu","es":"São Paulo"},{"en":"Rio de Janeiro","pron":"jíu dji yanéiru","es":"Río de Janeiro"},{"en":"Boa noite, até amanhã.","pron":"bóa nóichi, até amañã","es":"Buenas noches, hasta mañana."},{"en":"Eu trabalho na cidade.","pron":"éu trabáliu na sidádji","es":"Trabajo en la ciudad."},{"en":"Minha mãe não está.","pron":"míña mãi nãu istá","es":"Mi mamá no está."},{"en":"Um café com leite, por favor.","pron":"ũ kafé kõ léichi, pur favór","es":"Un café con leche, por favor."}]},{"tipo":"practica","rotulo":"¿Cómo suena?","preguntas":[{"p":"¿Cómo suena la palabra <i>dia</i>?","ops":["día","djía","zía"],"correcta":1,"explica":"La <b>d</b> antes de «i» suena <b>dj</b>."},{"p":"En <i>Rio</i>, la r inicial suena…","ops":["como la r de «perro»","como una j suave","como la r de «pero»"],"correcta":1},{"p":"<i>trabalho</i> se pronuncia aprox.…","ops":["trabálio","trabájo","trabáliu"],"correcta":2,"explica":"<b>lh</b> = «li» rápido, y la o final suena u."},{"p":"¿En qué palabra hay un sonido como nuestra ñ?","ops":["vinho","filho","praça"],"correcta":0},{"p":"<i>leite</i> suena aprox.…","ops":["léite","léichi","léite con e larga"],"correcta":1,"explica":"La <b>t</b> antes del sonido «i» (la e final suena i) se vuelve <b>chi</b>."}]},{"tipo":"pronunciar","rotulo":"Entrena la boca","frases":[{"en":"Eu moro no Rio de Janeiro.","pron":"éu móru nu jíu dji yanéiru","es":"Vivo en Río de Janeiro."},{"en":"Não, obrigado.","pron":"nãu, obrigádu","es":"No, gracias."},{"en":"Bom dia! Tudo bem?","pron":"bõ djía! túdu bẽi","es":"¡Buenos días! ¿Todo bien?"},{"en":"O meu filho trabalha amanhã.","pron":"u méu fíliu trabália amañã","es":"Mi hijo trabaja mañana."},{"en":"A praça fica perto da estação.","pron":"a prása fíka pértu da istasãu","es":"La plaza está cerca de la estación."}]},{"tipo":"clave","items":["<b>o</b> y <b>e</b> finales suenan <b>u</b> e <b>i</b>: <i>obrigado, leite</i>.","<b>ti/di</b> y <b>te/de</b> finales suenan <b>chi/dji</b>: <i>noite, dia, cidade</i>.","<b>ão, ões, ãe</b> y la m/n final son nasales; <b>lh</b> = li, <b>nh</b> = ñ, <b>ç</b> = s.","<b>r</b> inicial y <b>rr</b> = j suave. Pasa a la evaluación: necesitas 80%."]}],"c-portugues-a1-m2-l1":[{"tipo":"texto","texto":"Los números en portugués se parecen tanto a los nuestros que el peligro es decirlos en español sin darte cuenta. Cuida tres cosas: <b>1)</b> <b>um</b> y <b>dois</b> tienen femenino: <i>uma pessoa, duas pessoas</i>; <b>2)</b> del 16 al 19 se escriben <i>dezesseis, dezessete, dezoito, dezenove</i>; <b>3)</b> las decenas se unen siempre con <b>e</b>: <i>vinte e um, quarenta e cinco</i>.<br><br>Y un detalle que confunde a todos: al dictar un teléfono, un documento o un número de habitación, muchos brasileños dicen <b>meia</b> en lugar de <i>seis</i> (viene de <i>meia dúzia</i>, media docena), para no confundirlo con <i>três</i>."},{"tipo":"tabla","titulo":"Del 0 al 20","voz":true,"colVoz":0,"encabezados":["Portugués","Se lee aprox.","Número"],"filas":[["zero","zéru","0"],["um / uma","ũ / úma","1"],["dois / duas","dóis / dúas","2"],["três","três","3"],["quatro","kwátru","4"],["cinco","sĩku","5"],["seis (meia)","séis (méia)","6"],["sete","séchi","7"],["oito","óitu","8"],["nove","nóvi","9"],["dez","dés","10"],["onze · doze · treze","õzi · dôzi · trêzi","11 · 12 · 13"],["catorze · quinze","katôrzi · kĩzi","14 · 15"],["dezesseis · dezessete","dezeséis · dezeséchi","16 · 17"],["dezoito · dezenove","dezóitu · dezenóvi","18 · 19"],["vinte","vĩchi","20"]],"nota":"También se escribe <i>quatorze</i> (14). Las dos formas son correctas."},{"tipo":"tabla","titulo":"Las decenas","voz":true,"colVoz":0,"encabezados":["Portugués","Número"],"filas":[["vinte e um","21"],["trinta","30"],["quarenta","40"],["cinquenta","50"],["sessenta","60"],["setenta","70"],["oitenta","80"],["noventa","90"],["noventa e nove","99"],["cem","100"]]},{"tipo":"comparar","titulo":"Los números que se «españolizan»","malTitulo":"Evita","mal":"<i>dieciséis, diecisiete</i> con acento mexicano<br><i>cincuenta</i><br><i>dois pessoas</i><br><i>veinte e cinco</i>","bienTitulo":"Correcto","bien":"<i><b>dezesseis, dezessete</b></i><br><i><b>cinquenta</b></i> (sĩkwẽta)<br><i><b>duas</b> pessoas</i> (femenino)<br><i><b>vinte</b> e cinco</i> (vĩchi i sĩku)"},{"tipo":"dialogo","titulo":"Diálogo — Call center en Guadalajara","lineas":[{"quien":"Paola","en":"Central de atendimento, Paola falando. Bom dia!","es":"Centro de atención, habla Paola. ¡Buenos días!"},{"quien":"Sr. Marcos","en":"Bom dia, Paola. Eu preciso atualizar o meu telefone.","es":"Buenos días, Paola. Necesito actualizar mi teléfono."},{"quien":"Paola","en":"Claro, senhor. Qual é o número novo?","es":"Claro, señor. ¿Cuál es el número nuevo?"},{"quien":"Sr. Marcos","en":"É onze, nove, oito, sete, meia, cinco, quatro, três, dois, um.","es":"Es once, nueve, ocho, siete, seis, cinco, cuatro, tres, dos, uno."},{"quien":"Paola","en":"Só um momento… Onze, nove, oito, sete, meia, cinco, quatro, três, dois, um. Está correto?","es":"Un momento… Once, nueve, ocho, siete, seis, cinco, cuatro, tres, dos, uno. ¿Es correcto?"},{"quien":"Sr. Marcos","en":"Isso mesmo. Muito obrigado!","es":"Exacto. ¡Muchas gracias!"},{"quien":"Paola","en":"Imagina! Tenha um bom dia.","es":"¡No hay de qué! Que tenga buen día."}]},{"tipo":"practica","rotulo":"Números en contexto","preguntas":[{"p":"Un cliente dicta <i>três, meia, dois</i>. Anotas…","ops":["332","362","3062"],"correcta":1,"explica":"<b>meia</b> = seis (de <i>meia dúzia</i>)."},{"p":"«Dos mujeres» se dice…","ops":["dois mulheres","duas mulheres","dos mulheres"],"correcta":1},{"p":"¿Cómo se escribe 17?","ops":["dezessete","diecisete","dez e sete"],"correcta":0},{"p":"¿Cómo se dice 50?","ops":["cincuenta","cinquenta","cinqüenta e zero"],"correcta":1},{"p":"<i>noventa e oito</i> es…","ops":["89","98","908"],"correcta":1}]},{"tipo":"completar","rotulo":"Escribe el número en portugués","voz":true,"items":[{"frase":"Eu tenho ___ filhas.","resp":["duas"],"es":"Tengo dos hijas."},{"frase":"O quarto é o ___.","resp":["quinze"],"es":"La habitación es la 15."},{"frase":"São ___ e cinco pessoas.","resp":["vinte"],"es":"Son 25 personas."},{"frase":"O ônibus ___ vai para o centro.","resp":["dezesseis"],"es":"El camión 16 va al centro."},{"frase":"Custa ___ reais.","resp":["cem"],"es":"Cuesta 100 reales."}]},{"tipo":"clave","items":["<b>um/uma</b> y <b>dois/duas</b> cambian con el género.","16 a 19: <i>dezesseis, dezessete, dezoito, dezenove</i>.","Decenas y unidades siempre con <b>e</b>: <i>trinta e dois</i>.","Al dictar números, <b>meia</b> = 6."]}],"c-portugues-a1-m2-l2":[{"tipo":"texto","texto":"<b>Ter</b> es «tener» y se usa casi igual que en español: la edad (<i>Tenho 32 anos</i>), lo que posees (<i>Tenho um carro</i>) y las obligaciones con <b>ter que</b> (<i>Tenho que trabalhar</i>). Recuerda que el hambre, la sed y el frío van con <i>estar com</i> (lo viste en el módulo 1). Para números más grandes, fíjate en que 100 es <b>cem</b>, pero de 101 a 199 se dice <b>cento</b>: <i>cento e vinte</i>. Y las centenas tienen femenino: <i>duzentos reais</i>, pero <i>duzent<b>as</b> pessoas</i>."},{"tipo":"tabla","titulo":"Ter en presente","voz":true,"colVoz":0,"encabezados":["Portugués","Se lee aprox.","Español"],"filas":[["eu tenho","éu tẽñu","yo tengo"],["você tem","vosê tẽi","tú tienes"],["ele / ela tem","éli / éla tẽi","él / ella tiene"],["a gente tem","a yẽchi tẽi","nosotros tenemos (informal)"],["nós temos","nós têmus","nosotros tenemos"],["vocês têm","vosês tẽi","ustedes tienen"],["eles / elas têm","élis / élas tẽi","ellos / ellas tienen"]],"nota":"<i>tem</i> y <i>têm</i> suenan igual; el acento circunflejo solo marca el plural por escrito."},{"tipo":"tabla","titulo":"Números grandes","voz":true,"colVoz":0,"encabezados":["Portugués","Número"],"filas":[["cem","100"],["cento e cinquenta","150"],["duzentos / duzentas","200"],["trezentos","300"],["quinhentos","500"],["novecentos","900"],["mil","1000"],["mil e quinhentos","1500"],["dois mil e vinte e seis","2026"]]},{"tipo":"comparar","titulo":"Calcos con ter","malTitulo":"Evita","mal":"<i>Tenho 30 años.</i><br><i>Eu tem dois filhos.</i><br><i>Tengo que trabalhar.</i><br><i>cento reais</i> (para 100)","bienTitulo":"Correcto","bien":"<i>Tenho 30 <b>anos</b>.</i><br><i>Eu <b>tenho</b> dois filhos.</i><br><i><b>Tenho que</b> trabalhar.</i><br><i><b>cem</b> reais</i> · <i><b>cento e</b> dez reais</i>"},{"tipo":"dialogo","titulo":"Diálogo — Hora de la comida en una planta de Aguascalientes","lineas":[{"quien":"Ana","en":"Fernanda, você tem filhos?","es":"Fernanda, ¿tienes hijos?"},{"quien":"Fernanda","en":"Tenho, sim! Tenho duas filhas: a Sofia tem oito anos e a Laura tem cinco.","es":"¡Sí! Tengo dos hijas: Sofía tiene ocho años y Laura tiene cinco."},{"quien":"Ana","en":"Que lindo! Eu tenho um filho de doze anos.","es":"¡Qué bonito! Yo tengo un hijo de doce años."},{"quien":"Fernanda","en":"E vocês têm cachorro?","es":"¿Y ustedes tienen perro?"},{"quien":"Ana","en":"Temos! Ele se chama Chocolate e tem três anos.","es":"¡Sí! Se llama Chocolate y tiene tres años."},{"quien":"Fernanda","en":"Que fofo! Bom, agora tenho que voltar para a linha de produção.","es":"¡Qué lindo! Bueno, ahora tengo que regresar a la línea de producción."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«¿Cuántos años tienes?»","ops":["Quantos anos você tem?","Quantos años você tem?","Quanto anos tem você?"],"correcta":0},{"p":"En el diálogo, <i>cachorro</i> significa…","ops":["un cachorrito","un perro (de cualquier edad)","un gato"],"correcta":1,"explica":"Falso amigo: <b>cachorro</b> = perro. La cría es <i>filhote</i>."},{"p":"Vocês ___ carro?","ops":["tem","têm","temos"],"correcta":1},{"p":"«Tengo que trabajar el sábado.»","ops":["Tenho que trabalhar no sábado.","Tenho de trabalhar o sábado que.","Estou com trabalhar no sábado."],"correcta":0},{"p":"¿Cómo se dice «200 personas»?","ops":["duzentos pessoas","duzentas pessoas","dois cem pessoas"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa con ter","voz":true,"items":[{"frase":"Eu ___ trinta e cinco anos.","resp":["tenho"],"es":"Tengo 35 años."},{"frase":"A Fernanda ___ duas filhas.","resp":["tem"],"es":"Fernanda tiene dos hijas."},{"frase":"Nós ___ uma reunião às dez.","resp":["temos"],"es":"Tenemos una junta a las diez."},{"frase":"Eles ___ um cachorro.","resp":["têm","tem"],"es":"Ellos tienen un perro."},{"frase":"Eu tenho ___ trabalhar amanhã.","resp":["que","de"],"es":"Tengo que trabajar mañana."}]},{"tipo":"clave","items":["<b>ter</b>: <i>tenho, tem, temos, têm</i>.","Edad: <i>Tenho … anos</i>; obligación: <b>ter que</b> + verbo.","100 = <b>cem</b>; 101-199 = <b>cento e…</b>; centenas con femenino: <i>duzentas</i>.","Falso amigo: <b>cachorro</b> = perro."]}],"c-portugues-a1-m2-l3":[{"tipo":"texto","texto":"Las nacionalidades y profesiones funcionan como en español: cambian de masculino a femenino y van <b>sin artículo</b> después de <i>ser</i>: <i>Sou enfermeira</i>. Para preguntar a qué se dedica alguien: <b>O que você faz?</b> (¿Qué haces?) o <b>Com o que você trabalha?</b> (¿En qué trabajas?). Una respuesta muy brasileña es <i>Trabalho <b>com</b> vendas</i> (trabajo en ventas). Y cuidado: en Brasil la oficina es el <b>escritório</b>; la <i>oficina</i> es el taller mecánico."},{"tipo":"tabla","titulo":"Nacionalidades","voz":true,"colVoz":0,"encabezados":["Portugués (m / f)","Español"],"filas":[["mexicano / mexicana","mexicano / mexicana"],["brasileiro / brasileira","brasileño / brasileña"],["argentino / argentina","argentino / argentina"],["colombiano / colombiana","colombiano / colombiana"],["americano / americana","estadounidense"],["canadense","canadiense (igual en m y f)"],["espanhol / espanhola","español / española"],["português / portuguesa","portugués / portuguesa"],["alemão / alemã","alemán / alemana"],["japonês / japonesa","japonés / japonesa"]]},{"tipo":"tabla","titulo":"Profesiones","voz":true,"colVoz":0,"encabezados":["Portugués (m / f)","Español"],"filas":[["professor / professora","maestro / maestra"],["engenheiro / engenheira","ingeniero / ingeniera"],["enfermeiro / enfermeira","enfermero / enfermera"],["advogado / advogada","abogado / abogada"],["vendedor / vendedora","vendedor / vendedora"],["garçom / garçonete","mesero / mesera"],["cozinheiro / cozinheira","cocinero / cocinera"],["motorista","chofer, conductor (m y f)"],["atendente","agente de atención a clientes"],["operário / operária","obrero / obrera (de planta)"],["recepcionista","recepcionista"],["estudante","estudiante"]]},{"tipo":"comparar","titulo":"Falsos amigos del trabajo","malTitulo":"Parece que significa","mal":"<i>oficina</i> = oficina<br><i>escritório</i> = escritorio (el mueble)<br><i>Sou um engenheiro.</i> = soy ingeniero","bienTitulo":"En realidad","bien":"<i><b>oficina</b></i> = taller mecánico<br><i><b>escritório</b></i> = oficina; el mueble es <i>mesa</i> o <i>escrivaninha</i><br><i>Sou engenheiro.</i> (sin <i>um</i>, igual que en español)"},{"tipo":"dialogo","titulo":"Diálogo — Junta con proveedores brasileños en Monterrey","lineas":[{"quien":"Luciana","en":"Oi, eu sou a Luciana. Sou engenheira de produção.","es":"Hola, soy Luciana. Soy ingeniera de producción."},{"quien":"Javier","en":"Muito prazer, Luciana. Eu sou o Javier.","es":"Mucho gusto, Luciana. Yo soy Javier."},{"quien":"Luciana","en":"O prazer é meu. Com o que você trabalha, Javier?","es":"El gusto es mío. ¿En qué trabajas, Javier?"},{"quien":"Javier","en":"Sou contador. Trabalho no escritório da empresa, no centro.","es":"Soy contador. Trabajo en la oficina de la empresa, en el centro."},{"quien":"Luciana","en":"Ah, legal! E o seu colega?","es":"¡Ah, qué bien! ¿Y tu compañero?"},{"quien":"Javier","en":"O Toño é mecânico. Ele trabalha na oficina da fábrica.","es":"Toño es mecánico. Trabaja en el taller de la fábrica."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Un brasileño te dice <i>Meu carro está na oficina.</i> Su coche está…","ops":["en la oficina","en el taller mecánico","en el estacionamiento"],"correcta":1},{"p":"«Trabajo en una oficina»","ops":["Trabalho numa oficina.","Trabalho num escritório.","Trabalho numa escrivaninha."],"correcta":1},{"p":"Una mujer de Toronto es…","ops":["canadensa","canadense","canadiana"],"correcta":1},{"p":"«Soy mesera»","ops":["Sou garçonete.","Sou uma garçom.","Sou mesera."],"correcta":0},{"p":"«¿A qué te dedicas?»","ops":["O que você faz?","O que você é de trabalho?","Quem você trabalha?"],"correcta":0}]},{"tipo":"relacionar","rotulo":"Relaciona cada profesión","voz":true,"pares":[["advogada","abogada"],["motorista","chofer"],["garçom","mesero"],["engenheiro","ingeniero"],["atendente","agente de atención a clientes"],["professora","maestra"]]},{"tipo":"pronunciar","rotulo":"Dilo en voz alta","frases":[{"en":"Sou engenheira de produção.","pron":"sôu ẽyeñéira dji produsãu","es":"Soy ingeniera de producción."},{"en":"Ele é alemão e ela é brasileira.","pron":"éli é alemãu i éla é braziléira","es":"Él es alemán y ella es brasileña."},{"en":"Trabalho com vendas.","pron":"trabáliu kõ vẽdas","es":"Trabajo en ventas."},{"en":"Com o que você trabalha?","pron":"kõ u ki vosê trabália","es":"¿En qué trabajas?"}]},{"tipo":"clave","items":["Profesión sin artículo: <i>Sou enfermeira</i>.","<i>O que você faz? / Com o que você trabalha?</i>","<b>escritório</b> = oficina · <b>oficina</b> = taller mecánico.","<i>canadense</i> y <i>estudante</i> son iguales en masculino y femenino."]}],"c-portugues-a1-m2-l4":[{"tipo":"texto","texto":"Los artículos definidos del portugués son solo vocales: <b>o, a, os, as</b> (el, la, los, las). Los indefinidos: <b>um, uma, uns, umas</b>. Lo nuevo para ti son las <b>contracciones</b>: en español solo juntamos «de + el = del» y «a + el = al»; en portugués se juntan casi todas. Son obligatorias, no opcionales. Además, muchos países llevan artículo: <i>o Brasil, o México, a Argentina, os Estados Unidos</i>, así que se dice <i>Sou <b>do</b> México</i> y <i>Moro <b>no</b> Brasil</i>. Algunas palabras cambian de género respecto al español: <i><b>o</b> leite</i> (la leche), <i><b>a</b> viagem</i> (el viaje)."},{"tipo":"tabla","titulo":"Las contracciones que más usarás","voz":true,"colVoz":2,"encabezados":["Forma","Viene de","Ejemplo","Español"],"filas":[["do / dos","de + o / os","Sou do México.","Soy de México."],["da / das","de + a / as","Ela é da Colômbia.","Ella es de Colombia."],["no / nos","em + o / os","Moro no Brasil.","Vivo en Brasil."],["na / nas","em + a / as","Trabalho na fábrica.","Trabajo en la fábrica."],["num / numa","em + um / uma","Moro numa casa.","Vivo en una casa."],["ao / aos","a + o / os","Vou ao banco.","Voy al banco."],["à / às","a + a / as","Chego às oito.","Llego a las ocho."],["pelo / pela","por + o / a","Obrigado pela ajuda!","¡Gracias por la ayuda!"]],"nota":"Con ciudades normalmente no hay artículo: <i>Moro <b>em</b> Monterrey</i>, <i>Sou <b>de</b> Puebla</i>. Excepción famosa: <i><b>o</b> Rio</i> → <i>Moro <b>no</b> Rio</i>."},{"tipo":"comparar","titulo":"Contracciones que se olvidan","malTitulo":"Evita","mal":"<i>Sou de o México.</i><br><i>Moro em a Cidade do México.</i><br><i>A casa de a Ana.</i>","bienTitulo":"Correcto","bien":"<i>Sou <b>do</b> México.</i><br><i>Moro <b>na</b> Cidade do México.</i><br><i>A casa <b>da</b> Ana.</i>"},{"tipo":"tarjetas","rotulo":"Palabras que cambian de género","voz":true,"vozEn":"reverso","instruccion":"Ves la palabra en español; dila en portugués con su artículo antes de voltear. ¡Todas cambian de género!","tarjetas":[{"frente":"la leche","reverso":"o leite","ej":"O leite está frio."},{"frente":"el viaje","reverso":"a viagem","ej":"A viagem é longa."},{"frente":"la sangre","reverso":"o sangue","ej":"O exame de sangue."},{"frente":"la nariz","reverso":"o nariz","ej":"Estou com o nariz entupido."},{"frente":"el árbol","reverso":"a árvore","ej":"A árvore é muito alta."},{"frente":"la sal","reverso":"o sal","ej":"Me passa o sal?"},{"frente":"el color","reverso":"a cor","ej":"Qual é a sua cor favorita?"},{"frente":"el equipo","reverso":"a equipe","ej":"A equipe está pronta."}]},{"tipo":"practica","rotulo":"Elige la contracción","preguntas":[{"p":"Eu moro ___ Brasil.","ops":["em o","no","na"],"correcta":1},{"p":"Ela é ___ Argentina.","ops":["do","da","de a"],"correcta":1},{"p":"Nós trabalhamos ___ escritório.","ops":["no","na","num a"],"correcta":0},{"p":"Obrigada ___ informação!","ops":["pelo","pela","por a"],"correcta":1},{"p":"«La leche está en el refri.»","ops":["A leite está na geladeira.","O leite está na geladeira.","O leite está no geladeira."],"correcta":1,"explica":"<b>o leite</b> es masculino, y <i>geladeira</i> es femenino: <b>na</b> geladeira."}]},{"tipo":"completar","rotulo":"Completa con la contracción correcta","voz":true,"items":[{"frase":"O Paulo é ___ Rio de Janeiro.","resp":["do"],"es":"Paulo es de Río de Janeiro."},{"frase":"O meu escritório fica ___ Avenida Paulista.","resp":["na"],"es":"Mi oficina está en la Avenida Paulista."},{"frase":"Vou ___ supermercado.","resp":["ao","no"],"es":"Voy al súper."},{"frase":"A reunião é ___ duas.","resp":["às"],"es":"La junta es a las dos."},{"frase":"Moro ___ apartamento pequeno.","resp":["num","em um"],"es":"Vivo en un departamento pequeño."}]},{"tipo":"clave","items":["Artículos: <b>o, a, os, as</b> · <b>um, uma, uns, umas</b>.","de + o = <b>do</b>, em + a = <b>na</b>, a + o = <b>ao</b>, a + a = <b>à</b>: siempre se juntan.","<i>o Brasil, o México, a Argentina</i> llevan artículo: <i>Sou do México.</i>","Ojo al género: <i>o leite, a viagem, o sal, a cor</i>."]}],"c-portugues-a1-m2-l5":[{"tipo":"texto","texto":"Las palabras para preguntar son muy parecidas al español, con algunos cambios de forma. La más importante: «¿Qué?» es <b>O que?</b> (se lee «u ki»). Para preguntas de sí o no, basta con subir la entonación: <i>Você é brasileiro?</i> Y cuidado con los datos personales: en portugués tu apellido es el <b>sobrenome</b>. Si le dices a un brasileño que tu <i>apelido</i> es García, va a entender que así te dicen de cariño."},{"tipo":"tabla","titulo":"Palabras para preguntar","voz":true,"colVoz":1,"encabezados":["Palabra","Ejemplo","Español"],"filas":[["Quem?","Quem é ela?","¿Quién es ella?"],["O que?","O que você faz?","¿Qué haces?"],["Onde?","Onde você mora?","¿Dónde vives?"],["De onde?","De onde você é?","¿De dónde eres?"],["Quando?","Quando é o seu aniversário?","¿Cuándo es tu cumpleaños?"],["Como?","Como se escreve?","¿Cómo se escribe?"],["Qual? / Quais?","Qual é o seu e-mail?","¿Cuál es tu correo?"],["Quanto? / Quantos?","Quantos anos você tem?","¿Cuántos años tienes?"],["Por que?","Por que você estuda português?","¿Por qué estudias portugués?"]],"nota":"La respuesta a <i>Por que?</i> es <b>porque</b>, junto: <i>Porque eu trabalho com brasileiros.</i> En el correo, @ es <b>arroba</b> y el punto es <b>ponto</b>."},{"tipo":"comparar","titulo":"Falsos amigos de los datos personales","malTitulo":"Parece que significa","mal":"<i>apelido</i> = apellido<br><i>firma</i> = tu firma en un documento<br><i>direção</i> = tu domicilio","bienTitulo":"En realidad","bien":"<i><b>apelido</b></i> = apodo; el apellido es <b>sobrenome</b><br><i><b>firma</b></i> = empresa; tu firma es <b>assinatura</b><br><i><b>direção</b></i> = rumbo o dirección de una empresa; tu domicilio es <b>endereço</b>"},{"tipo":"dialogo","titulo":"Diálogo — Inscripción a un curso de español en Guanajuato","lineas":[{"quien":"Lupita","en":"Qual é o seu nome completo?","es":"¿Cuál es tu nombre completo?"},{"quien":"Thiago","en":"Thiago Oliveira Santos.","es":"Thiago Oliveira Santos."},{"quien":"Lupita","en":"E o seu sobrenome é Santos?","es":"¿Y tu apellido es Santos?"},{"quien":"Thiago","en":"É, sim. Mas todo mundo me chama de Thi. É o meu apelido.","es":"Sí. Pero todos me dicen Thi. Es mi apodo."},{"quien":"Lupita","en":"Tá bom! Qual é o seu endereço aqui?","es":"¡Muy bien! ¿Cuál es tu domicilio aquí?"},{"quien":"Thiago","en":"Rua Positos, número quarenta e cinco, no centro.","es":"Calle Positos, número cuarenta y cinco, en el centro."},{"quien":"Lupita","en":"E o seu e-mail?","es":"¿Y tu correo?"},{"quien":"Thiago","en":"É thiago ponto santos arroba email ponto com.","es":"Es thiago punto santos arroba email punto com."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"En un formulario brasileño, ¿dónde va «García»?","ops":["apelido","sobrenome","assinatura"],"correcta":1},{"p":"«¿Qué haces?»","ops":["Que você faz?","O que você faz?","Qué você faz?"],"correcta":1},{"p":"Te piden tu <i>endereço</i>. Das…","ops":["tu domicilio","tu apodo","tu firma"],"correcta":0},{"p":"«¿Por qué?» y «porque» se escriben…","ops":["Por que? / porque","Porque? / por que","Por qué? / por qué"],"correcta":0},{"p":"<i>Assine aqui, por favor.</i> Te están pidiendo…","ops":["tu apodo","tu firma","tu dirección"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Arma las preguntas","voz":true,"items":[{"frase":"Qual é o seu sobrenome?","es":"¿Cuál es tu apellido?"},{"frase":"Onde você mora agora?","es":"¿Dónde vives ahora?"},{"frase":"Quando é o seu aniversário?","es":"¿Cuándo es tu cumpleaños?"},{"frase":"Por que você estuda português?","es":"¿Por qué estudias portugués?"}]},{"tipo":"reflexion","rotulo":"Tu ficha en portugués","pregunta":"Contesta por escrito, con tus datos reales o inventados: Qual é o seu nome completo? Qual é o seu sobrenome? Você tem apelido? Quantos anos você tem? De onde você é? Onde você mora? O que você faz? Qual é o seu telefone? Después léelas en voz alta.","ayuda":"Meu nome completo é… Meu sobrenome é… Meu apelido é… Tenho … anos. Sou de… Moro em… Sou … (profissão). Meu telefone é…"},{"tipo":"clave","items":["<i>Quem, o que, onde, quando, como, qual, quanto, por que</i>.","<b>sobrenome</b> = apellido · <b>apelido</b> = apodo.","<b>endereço</b> = domicilio · <b>assinatura</b> = firma · <b>firma</b> = empresa.","@ = <b>arroba</b> · punto = <b>ponto</b>. Pasa a la evaluación: necesitas 80%."]}],"c-portugues-a1-m3-l1":[{"tipo":"texto","texto":"Los verbos regulares del portugués se parecen mucho a los del español, y tienen <b>menos formas</b> gracias a <i>você</i> y <i>a gente</i>, que usan el verbo de «él». En la práctica solo necesitas cuatro terminaciones: <b>eu</b> (-o), <b>você / ele / ela / a gente</b> (-a o -e), <b>nós</b> (-amos, -emos, -imos, igual que en español) y <b>vocês / eles / elas</b> (-am o -em, con sonido nasal). Pocos verbos se salen de la regla en el presente; uno muy común es <b>fazer</b> (hacer): <i>eu faço, você faz, nós fazemos, eles fazem</i>."},{"tipo":"tabla","titulo":"Tres verbos modelo","voz":true,"colVoz":1,"encabezados":["Persona","falar (hablar)","comer","abrir"],"filas":[["eu","falo","como","abro"],["você / ele / ela / a gente","fala","come","abre"],["nós","falamos","comemos","abrimos"],["vocês / eles / elas","falam","comem","abrem"]],"nota":"<i>falam</i> suena «fálãu» y <i>comem</i> suena «kómẽi»: la m final no se pronuncia, solo nasaliza."},{"tipo":"tabla","titulo":"Verbos para tu vida diaria","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Eu trabalho numa fábrica.","Trabajo en una fábrica."],["Eu estudo inglês e português.","Estudio inglés y portugués."],["Você fala espanhol?","¿Hablas español?"],["A gente mora perto do centro.","Vivimos cerca del centro."],["Eles bebem muito café.","Ellos toman mucho café."],["Eu escrevo e-mails em inglês.","Escribo correos en inglés."],["Nós abrimos a loja às nove.","Abrimos la tienda a las nueve."],["O que você faz no fim de semana?","¿Qué haces el fin de semana?"]],"nota":"«Tomar» café o agua se dice <b>tomar</b> o <b>beber</b>; las dos son correctas."},{"tipo":"comparar","titulo":"Terminaciones que se contagian del español","malTitulo":"Evita","mal":"<i>Você falas português?</i><br><i>Eles trabalhan muito.</i><br><i>Eu hago o relatório.</i>","bienTitulo":"Correcto","bien":"<i>Você <b>fala</b> português?</i> (sin -s: <i>você</i> usa el verbo de «él»)<br><i>Eles <b>trabalham</b> muito.</i> (-am, nasal)<br><i>Eu <b>faço</b> o relatório.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Turno de noche en un call center de Monterrey","lineas":[{"quien":"Bruno","en":"Oi! Você é novo aqui, né? Eu sou o Bruno.","es":"¡Hola! Eres nuevo aquí, ¿verdad? Yo soy Bruno."},{"quien":"Iván","en":"Sou, sim. Me chamo Iván. Você fala espanhol?","es":"Sí. Me llamo Iván. ¿Hablas español?"},{"quien":"Bruno","en":"Falo um pouco. Aqui a gente atende clientes do Brasil.","es":"Hablo un poco. Aquí atendemos a clientes de Brasil."},{"quien":"Iván","en":"Eu sei. Eu estudo português à noite, depois do trabalho.","es":"Ya sé. Estudio portugués en la noche, después del trabajo."},{"quien":"Bruno","en":"Que bom! E o que você faz de dia?","es":"¡Qué bien! ¿Y qué haces de día?"},{"quien":"Iván","en":"De dia eu durmo, né! Trabalho de noite.","es":"¡De día duermo, obvio! Trabajo de noche."}]},{"tipo":"practica","rotulo":"Elige la forma correcta","preguntas":[{"p":"Você ___ inglês?","ops":["falas","fala","falo"],"correcta":1},{"p":"Nós ___ às oito.","ops":["comemos","comem","comimos"],"correcta":0,"explica":"En presente: <b>comemos</b>, igual que en español."},{"p":"Eles ___ numa escola.","ops":["trabalhan","trabalham","trabalhamos"],"correcta":1},{"p":"«Yo hago la comida»","ops":["Eu faço a comida.","Eu hago a comida.","Eu faz a comida."],"correcta":0},{"p":"<i>né?</i> al final de una frase significa…","ops":["¿verdad?","no","nada"],"correcta":0,"explica":"<b>né</b> viene de <i>não é</i> y es como nuestro «¿verdad?» o «¿no?»."}]},{"tipo":"completar","rotulo":"Conjuga el verbo","voz":true,"items":[{"frase":"Eu ___ português à noite.","resp":["estudo"],"es":"Estudio portugués en la noche."},{"frase":"A Luciana ___ numa empresa alemã.","resp":["trabalha"],"es":"Luciana trabaja en una empresa alemana."},{"frase":"Vocês ___ carne?","resp":["comem"],"es":"¿Ustedes comen carne?"},{"frase":"Nós ___ a loja às nove.","resp":["abrimos"],"es":"Abrimos la tienda a las nueve."},{"frase":"O que você ___ no sábado?","resp":["faz"],"es":"¿Qué haces el sábado?"}]},{"tipo":"clave","items":["Cuatro formas: <i>falo, fala, falamos, falam</i>.","<i>você</i> y <i>a gente</i> usan el verbo de «él»: <i>você fala, a gente fala</i>.","Plural nasal: <i>falam, comem, abrem</i>.","<b>fazer</b>: <i>faço, faz, fazemos, fazem</i>."]}],"c-portugues-a1-m3-l2":[{"tipo":"texto","texto":"Para contar tu día necesitas unos diez verbos. Varios se parecen a los del español pero engañan: en portugués <b>acordar</b> es despertar, <b>pegar</b> es tomar o agarrar (<i>pegar o ônibus</i> = tomar el camión), <b>assistir</b> es ver (la tele, un partido) y <b>jantar</b> es cenar. Otro detalle: con los verbos reflexivos, en Brasil el pronombre casi siempre va <b>antes</b> del verbo: <i>Eu <b>me</b> levanto às seis.</i>"},{"tipo":"tabla","titulo":"Un día normal","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Eu acordo às seis.","Me despierto a las seis."],["Eu me levanto e tomo banho.","Me levanto y me baño."],["Tomo café da manhã em casa.","Desayuno en casa."],["Pego o ônibus às sete.","Tomo el camión a las siete."],["Começo a trabalhar às oito.","Empiezo a trabajar a las ocho."],["Almoço ao meio-dia.","Como al mediodía."],["Volto para casa às seis.","Regreso a casa a las seis."],["Janto com a minha família.","Ceno con mi familia."],["Assisto TV um pouco.","Veo un poco la tele."],["Vou dormir às onze.","Me duermo a las once."]],"nota":"<b>café da manhã</b> es el desayuno; <b>almoço</b>, la comida del mediodía; <b>jantar</b>, la cena. En Brasil se come fuerte entre las 12 y la 1."},{"tipo":"comparar","titulo":"Falsos amigos de la rutina","malTitulo":"Parece que significa","mal":"<i>acordar</i> = acordarse, recordar<br><i>pegar</i> = pegar, golpear<br><i>assistir</i> = asistir a clases<br><i>cena</i> = cena","bienTitulo":"En realidad","bien":"<i><b>acordar</b></i> = despertar(se); recordar es <b>lembrar</b><br><i><b>pegar</b></i> = tomar, agarrar; pegar con pegamento es <b>colar</b><br><i><b>assistir</b></i> = ver (TV, un partido); ir a clases es <b>ir à aula</b><br><i><b>cena</b></i> = escena; la cena es el <b>jantar</b>"},{"tipo":"dialogo","titulo":"Diálogo — Un ingeniero brasileño en una planta de Silao","lineas":[{"quien":"Rafael","en":"A que horas você acorda, Lupita?","es":"¿A qué hora te despiertas, Lupita?"},{"quien":"Lupita","en":"Acordo às cinco! Pego o ônibus da empresa às seis.","es":"¡Me despierto a las cinco! Tomo el camión de la empresa a las seis."},{"quien":"Rafael","en":"Nossa, que cedo! E você toma café da manhã em casa?","es":"¡Híjole, qué temprano! ¿Y desayunas en casa?"},{"quien":"Lupita","en":"Não, tomo café aqui no refeitório. E almoço à uma.","es":"No, desayuno aquí en el comedor. Y como a la una."},{"quien":"Rafael","en":"E à noite?","es":"¿Y en la noche?"},{"quien":"Lupita","en":"Janto com os meus filhos, assisto uma série e vou dormir cedo.","es":"Ceno con mis hijos, veo una serie y me duermo temprano."}]},{"tipo":"tarjetas","rotulo":"Verbos de la rutina","voz":true,"vozEn":"reverso","instruccion":"Ves el verbo en español; dilo en portugués antes de voltear.","tarjetas":[{"frente":"despertar(se)","reverso":"acordar","ej":"Eu acordo às seis."},{"frente":"recordar","reverso":"lembrar","ej":"Não lembro o nome dele."},{"frente":"tomar (el camión)","reverso":"pegar","ej":"Pego o metrô todo dia."},{"frente":"desayunar","reverso":"tomar café da manhã","ej":"Tomo café da manhã às sete."},{"frente":"comer (al mediodía)","reverso":"almoçar","ej":"A gente almoça à uma."},{"frente":"cenar","reverso":"jantar","ej":"Vamos jantar fora hoje?"},{"frente":"ver (la tele)","reverso":"assistir","ej":"Assisto futebol no domingo."},{"frente":"regresar","reverso":"voltar","ej":"Volto para casa às seis."}]},{"tipo":"practica","rotulo":"¿Qué significa?","preguntas":[{"p":"<i>Eu acordo às cinco.</i>","ops":["Me acuerdo a las cinco.","Me despierto a las cinco.","Quedo de acuerdo a las cinco."],"correcta":1},{"p":"<i>Vou pegar um táxi.</i>","ops":["Voy a tomar un taxi.","Voy a pegarle a un taxi.","Voy a pagar un taxi."],"correcta":0},{"p":"«Anoche vi el partido» usa el verbo…","ops":["assistir","atender","asistir"],"correcta":0},{"p":"«No recuerdo»","ops":["Não acordo.","Não lembro.","Não pego."],"correcta":1},{"p":"Un brasileño dice <i>Que cena linda!</i> viendo una película. Habla de…","ops":["una cena","una escena","un plato"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Ordena tu mañana","voz":true,"items":[{"frase":"Eu me levanto às seis e meia","es":"Me levanto a las seis y media"},{"frase":"Tomo café da manhã com a minha filha","es":"Desayuno con mi hija"},{"frase":"Pego o metrô para o trabalho","es":"Tomo el metro para ir al trabajo"},{"frase":"Começo a trabalhar às oito","es":"Empiezo a trabajar a las ocho"}]},{"tipo":"clave","items":["<b>acordar</b> = despertar · <b>lembrar</b> = recordar.","<b>pegar</b> el camión o un taxi; <b>colar</b> con pegamento.","<b>café da manhã</b>, <b>almoço</b>, <b>jantar</b>; <b>cena</b> = escena.","<b>assistir</b> TV = ver la tele. Reflexivos con el pronombre antes: <i>Eu me levanto</i>."]}],"c-portugues-a1-m3-l3":[{"tipo":"texto","texto":"Para preguntar la hora: <b>Que horas são?</b> Para contestar, usas <b>é</b> con la una, el mediodía y la medianoche, y <b>são</b> con todas las demás: <i>É uma hora, são duas horas</i>. A diferencia del español, <b>no hay artículo</b>: no se dice «são as duas», sino <i>são duas</i>. Para decir a qué hora pasa algo usas <b>às</b> (a + as): <i>às oito</i>, y con la una, <b>à</b>: <i>à uma</i>. En horarios oficiales (vuelos, oficinas, TV) los brasileños usan mucho el reloj de 24 horas: <i>às dezoito horas</i>."},{"tipo":"tabla","titulo":"La hora","voz":true,"colVoz":0,"encabezados":["Portugués","Hora"],"filas":[["É uma hora.","1:00"],["São duas horas.","2:00"],["São três e quinze.","3:15"],["São quatro e meia.","4:30"],["São quinze para as seis.","5:45"],["São oito e dez da manhã.","8:10 a. m."],["São três da tarde.","3:00 p. m."],["São nove da noite.","9:00 p. m."],["É meio-dia.","12:00 del día"],["É meia-noite.","12:00 de la noche"]],"nota":"5:45 también se dice <i>Faltam quinze para as seis</i> o, en horario oficial, <i>cinco e quarenta e cinco</i>."},{"tipo":"comparar","titulo":"La hora sin artículo","malTitulo":"Evita","mal":"<i>São as duas.</i><br><i>A reunião é a las oito.</i><br><i>Chego às uma.</i><br><i>É meio-dia e meio.</i>","bienTitulo":"Correcto","bien":"<i>São <b>duas</b>.</i><br><i>A reunião é <b>às</b> oito.</i><br><i>Chego <b>à</b> uma.</i><br><i>É meio-dia e <b>meia</b>.</i> (media hora)"},{"tipo":"escuchar","rotulo":"Escucha y escribe la hora","frases":[{"en":"São sete e vinte.","pron":"sãu séchi i vĩchi","es":"Son las 7:20."},{"en":"O voo sai às dezoito horas.","pron":"u vôu sai às dezóitu óras","es":"El vuelo sale a las 18:00."},{"en":"A loja abre às nove e fecha às dez da noite.","es":"La tienda abre a las 9 y cierra a las 10 de la noche."},{"en":"É meio-dia e meia.","pron":"é méiu djía i méia","es":"Son las 12:30."},{"en":"A gente se vê à uma, tá?","pron":"a yẽchi si vê a úma, tá","es":"Nos vemos a la una, ¿va?"}]},{"tipo":"dialogo","titulo":"Diálogo — Recepción de un hotel en Tulum","lineas":[{"quien":"Sr. Gustavo","en":"Com licença, que horas são?","es":"Disculpe, ¿qué hora es?"},{"quien":"Recepcionista","en":"São dez e quinze, senhor.","es":"Son las diez y cuarto, señor."},{"quien":"Sr. Gustavo","en":"E a que horas sai o passeio para as ruínas?","es":"¿Y a qué hora sale la excursión a las ruinas?"},{"quien":"Recepcionista","en":"Às onze. O ônibus volta às cinco da tarde.","es":"A las once. El camión regresa a las cinco de la tarde."},{"quien":"Sr. Gustavo","en":"E o restaurante fecha a que horas?","es":"¿Y a qué hora cierra el restaurante?"},{"quien":"Recepcionista","en":"À meia-noite. Bom passeio!","es":"A la medianoche. ¡Que disfrute la excursión!"}]},{"tipo":"practica","rotulo":"¿Qué hora es?","preguntas":[{"p":"<i>São quinze para as nove.</i>","ops":["9:15","8:45","9:45"],"correcta":1},{"p":"1:00 p. m. se dice…","ops":["São uma hora.","É uma hora.","É a uma."],"correcta":1},{"p":"«La junta es a las tres.»","ops":["A reunião é às três.","A reunião é a las três.","A reunião são três."],"correcta":0},{"p":"<i>às vinte horas</i> es…","ops":["a las 8 p. m.","a las 2 p. m.","en 20 horas"],"correcta":0},{"p":"«Son las doce y media del día»","ops":["É meio-dia e meia.","São doze e meio.","É meia-noite e meia."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la hora","voz":true,"items":[{"frase":"Que horas ___?","resp":["são"],"es":"¿Qué hora es?"},{"frase":"___ uma e vinte.","resp":["É"],"es":"Es la una y veinte."},{"frase":"O almoço é ___ meio-dia.","resp":["ao"],"es":"La comida es al mediodía."},{"frase":"Eu saio do trabalho ___ seis.","resp":["às"],"es":"Salgo del trabajo a las seis."},{"frase":"São cinco e ___.","resp":["meia"],"es":"Son las cinco y media."}]},{"tipo":"clave","items":["<i>Que horas são?</i> — <i>É uma hora / São duas horas.</i>","Sin artículo: <i>são duas</i>; «a las» = <b>às</b>, «a la una» = <b>à uma</b>.","<i>e meia</i> = y media · <i>quinze para as…</i> = cuarto para las…","Horarios oficiales en 24 horas: <i>às dezoito horas</i>."]}],"c-portugues-a1-m3-l4":[{"tipo":"texto","texto":"Los días de la semana son la gran sorpresa del portugués: de lunes a viernes <b>se cuentan con números</b>. El lunes es <i>segunda-feira</i> (la segunda feria, porque el domingo es el primer día), el martes <i>terça-feira</i>, y así hasta el viernes, <i>sexta-feira</i>. En la plática casi siempre se quita el <i>-feira</i>: <i>Até segunda!</i> Sábado y domingo se parecen al español. Los días y los meses se escriben <b>con minúscula</b>. Para decir «el lunes» se usa <b>na</b> (<i>na segunda</i>) y para «el sábado», <b>no</b> (<i>no sábado</i>)."},{"tipo":"tabla","titulo":"Los días de la semana","voz":true,"colVoz":0,"encabezados":["Portugués","Se lee aprox.","Español"],"filas":[["segunda-feira","segũda féira","lunes"],["terça-feira","térsa féira","martes"],["quarta-feira","kwárta féira","miércoles"],["quinta-feira","kĩta féira","jueves"],["sexta-feira","sésta féira","viernes"],["sábado","sábadu","sábado"],["domingo","domĩgu","domingo"],["o fim de semana","u fĩ dji semãna","el fin de semana"]],"nota":"«De lunes a viernes» = <i>de segunda a sexta</i>. «Los lunes» = <i>às segundas</i> o <i>toda segunda</i>."},{"tipo":"tabla","titulo":"Los meses","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["janeiro · fevereiro · março","enero · febrero · marzo"],["abril · maio · junho","abril · mayo · junio"],["julho · agosto · setembro","julio · agosto · septiembre"],["outubro · novembro · dezembro","octubre · noviembre · diciembre"]],"nota":"Fechas: <i>Hoje é dia 16 de setembro.</i> · <i>Meu aniversário é <b>no dia</b> 12 de junho.</i> · <i><b>Em</b> dezembro</i> (en diciembre)."},{"tipo":"comparar","titulo":"Calcos con los días","malTitulo":"Evita","mal":"<i>O lunes tenho reunião.</i><br><i>A reunião é o segunda.</i><br><i>Trabalho de lunes a viernes.</i><br><i>Em o fim de semana</i>","bienTitulo":"Correcto","bien":"<i><b>Na segunda</b> tenho reunião.</i><br><i>A reunião é <b>na</b> segunda.</i> (<i>segunda</i> es femenino)<br><i>Trabalho <b>de segunda a sexta</b>.</i><br><i><b>No</b> fim de semana</i>"},{"tipo":"dialogo","titulo":"Diálogo — Agendar una visita con una clienta de São Paulo","lineas":[{"quien":"Mariana","en":"Oi, Carlos! Podemos marcar a visita à fábrica?","es":"¡Hola, Carlos! ¿Podemos agendar la visita a la fábrica?"},{"quien":"Carlos","en":"Claro! Pode ser na quinta-feira, dia 13?","es":"¡Claro! ¿Puede ser el jueves 13?"},{"quien":"Mariana","en":"Quinta eu não posso. Tenho reunião o dia todo.","es":"El jueves no puedo. Tengo juntas todo el día."},{"quien":"Carlos","en":"E na sexta, dia 14?","es":"¿Y el viernes 14?"},{"quien":"Mariana","en":"Sexta é perfeito. Às dez da manhã?","es":"El viernes es perfecto. ¿A las diez de la mañana?"},{"quien":"Carlos","en":"Combinado! Sexta, 14 de novembro, às dez.","es":"¡Quedamos! Viernes 14 de noviembre, a las diez."}]},{"tipo":"relacionar","rotulo":"Relaciona cada día","voz":true,"pares":[["segunda-feira","lunes"],["terça-feira","martes"],["quarta-feira","miércoles"],["quinta-feira","jueves"],["sexta-feira","viernes"],["domingo","domingo"]]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Un cliente te dice <i>Até terça!</i> Lo vas a ver el…","ops":["martes","miércoles","tercer día del mes"],"correcta":0},{"p":"«El sábado voy a la playa.»","ops":["Na sábado vou à praia.","No sábado vou à praia.","O sábado vou à praia."],"correcta":1},{"p":"«Mi cumpleaños es el 5 de mayo.»","ops":["Meu aniversário é no dia 5 de maio.","Meu aniversário é o 5 de Maio.","Meu aniversário é em 5 maio."],"correcta":0},{"p":"<i>Combinado!</i> significa…","ops":["¡Mezclado!","¡Quedamos! / ¡Trato hecho!","¡Qué combinación!"],"correcta":1},{"p":"¿Cómo se escribe correctamente?","ops":["Segunda-Feira, Março","segunda-feira, março","segunda-feira, Março"],"correcta":1}]},{"tipo":"clave","items":["Lunes a viernes con números: <i>segunda, terça, quarta, quinta, sexta</i> (-feira).","«El lunes» = <b>na</b> segunda · «el sábado» = <b>no</b> sábado.","Días y meses con minúscula; fechas: <i>no dia 12 de junho</i>.","<i>Combinado!</i> = ¡Quedamos!"]}],"c-portugues-a1-m3-l5":[{"tipo":"texto","texto":"En español decimos «<i>me</i> gusta el café»: el café es el que gusta. En portugués es al revés, como en inglés: <b>tú</b> eres el sujeto y el verbo lleva <b>de</b>: <i>Eu <b>gosto de</b> café</i>. Con artículo, se contrae: <i>Gosto <b>do</b> Brasil, gosto <b>da</b> comida mexicana</i>. Para contestar, se repite el verbo: <i>Você gosta de futebol? — <b>Gosto!</b></i><br><br>La negación es fácil: <b>não</b> antes del verbo. Y muy brasileño: repetir <i>não</i> al final para suavizar o reforzar: <i>Não gosto não.</i> Como en español, se permite la doble negación: <i>Não como nada</i>, <i>Não conheço ninguém</i>."},{"tipo":"tabla","titulo":"Gustos y preferencias","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Eu gosto de café.","Me gusta el café."],["Eu gosto muito do Brasil.","Me gusta mucho Brasil."],["Você gosta de dançar?","¿Te gusta bailar?"],["Gosto! / Não gosto.","¡Sí me gusta! / No me gusta."],["Eu adoro praia.","Me encanta la playa."],["Prefiro chá.","Prefiero té."],["Eu odeio trânsito.","Odio el tráfico."],["Não gosto de acordar cedo, não.","No me gusta despertarme temprano."],["Nunca como carne.","Nunca como carne."]]},{"tipo":"comparar","titulo":"«Me gusta» no se traduce palabra por palabra","malTitulo":"Evita","mal":"<i>Me gosta o café.</i><br><i>Eu gosto o Brasil.</i><br><i>Me gostam os tacos.</i><br><i>— Você gosta? — Sim.</i> (correcto, pero seco)","bienTitulo":"Correcto","bien":"<i>Eu <b>gosto de</b> café.</i><br><i>Eu gosto <b>do</b> Brasil.</i><br><i>Eu <b>gosto de</b> tacos.</i><br><i>— Você gosta? — <b>Gosto!</b></i>"},{"tipo":"comparar","titulo":"Esquisito no es exquisito","malTitulo":"Parece que significa","mal":"<i>Que comida esquisita!</i> = ¡Qué comida tan exquisita!<br><i>exquisito</i> = delicioso","bienTitulo":"En realidad","bien":"<i><b>esquisito</b></i> = raro, extraño. ¡Es casi un insulto para el cocinero!<br>Para elogiar la comida: <b>delicioso</b>, <b>gostoso</b>, <b>uma delícia</b>. (<i>Gostoso</i> úsalo para la comida: dicho de una persona significa «guapo», con picardía.)"},{"tipo":"dialogo","titulo":"Diálogo — Mercado en Oaxaca con turistas brasileños","lineas":[{"quien":"Rodrigo","en":"Vocês gostam de comida apimentada?","es":"¿Les gusta la comida picante?"},{"quien":"Camila","en":"Eu gosto muito! O Paulo não gosta não.","es":"¡A mí me gusta mucho! A Paulo no."},{"quien":"Paulo","en":"Gosto, sim, mas pouca pimenta, por favor!","es":"Sí me gusta, ¡pero poco chile, por favor!"},{"quien":"Rodrigo","en":"E gafanhoto? Vocês querem provar?","es":"¿Y chapulines? ¿Quieren probar?"},{"quien":"Paulo","en":"Gafanhoto? Que esquisito! Eu não como inseto, não.","es":"¿Chapulines? ¡Qué raro! Yo no como insectos."},{"quien":"Camila","en":"Eu quero! Hum… é uma delícia! Prova, Paulo!","es":"¡Yo sí! Mmm… ¡está delicioso! ¡Prueba, Paulo!"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Me gusta la música brasileña»","ops":["Me gosta a música brasileira.","Eu gosto da música brasileira.","Eu gosto a música brasileira."],"correcta":1},{"p":"Te preguntan <i>Você gosta de praia?</i> y te encanta. Respuesta natural:","ops":["Gosto muito!","Sim, me gosta.","Gosta, sim."],"correcta":0},{"p":"Pruebas una moqueca y te encanta. Dices…","ops":["Que esquisito!","Que delícia!","Que exquisita!"],"correcta":1,"explica":"<b>esquisito</b> = raro. Para elogiar: <i>delícia, delicioso, gostoso</i>."},{"p":"«No conozco a nadie aquí.»","ops":["Não conheço ninguém aqui.","Conheço ninguém não aqui.","Não conheço nadie aqui."],"correcta":0},{"p":"«A ella le gustan los perros.»","ops":["Ela gosta de cachorros.","Ela gostam de cachorros.","A ela gostam os cachorros."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa con gostar de","voz":true,"items":[{"frase":"Eu ___ de chocolate.","resp":["gosto"],"es":"Me gusta el chocolate."},{"frase":"Você gosta ___ futebol?","resp":["de"],"es":"¿Te gusta el futbol?"},{"frase":"A gente gosta muito ___ comida baiana.","resp":["da"],"es":"Nos gusta mucho la comida bahiana."},{"frase":"Eles ___ gostam de acordar cedo.","resp":["não"],"es":"A ellos no les gusta despertarse temprano."},{"frase":"Ela gosta muito ___ Rio de Janeiro.","resp":["do"],"es":"A ella le gusta mucho Río de Janeiro."}]},{"tipo":"clave","items":["<b>Eu gosto de…</b>: tú eres el sujeto, y siempre con <b>de</b> (<i>do, da</i>).","Para contestar, repite el verbo: <i>Gosto! / Não gosto.</i>","<b>não</b> antes del verbo; a la brasileña: <i>Não gosto não</i>.","<b>esquisito</b> = raro; la comida rica es <b>uma delícia</b>. Pasa a la evaluación: necesitas 80%."]}],"c-portugues-a1-m4-l1":[{"tipo":"texto","texto":"En el portugués escrito formal, «hay» es <b>há</b>. Pero en la conversación de Brasil casi todo el mundo usa <b>tem</b>: <i><b>Tem</b> uma farmácia aqui perto?</i> (¿Hay una farmacia cerca?). Para contestar: <i>Tem, sim</i> o <i>Não tem</i>. Es la frase que más vas a usar al llegar a una ciudad nueva. Y para saber <b>dónde está</b> un lugar, usa <b>Onde fica…?</b>, que viste en el módulo 1."},{"tipo":"tabla","titulo":"Lugares de la ciudad","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["a farmácia","la farmacia"],["o banco · o caixa eletrônico","el banco · el cajero automático"],["a padaria","la panadería (y cafetería)"],["o supermercado · o mercado","el súper · el mercado"],["o ponto de ônibus","la parada del camión"],["a estação de metrô","la estación del metro"],["a praça","la plaza"],["o posto de gasolina","la gasolinera"],["o banheiro","el baño"],["a rua · a avenida · a calçada","la calle · la avenida · la banqueta"]],"nota":"La <b>padaria</b> brasileña es mucho más que una panadería: ahí se desayuna, se toma café y hasta se come."},{"tipo":"tabla","titulo":"Preguntas con tem","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Tem uma farmácia aqui perto?","¿Hay una farmacia cerca?"],["Tem, sim. Fica na esquina.","Sí hay. Está en la esquina."],["Não tem. Só no shopping.","No hay. Solo en la plaza comercial."],["Onde tem um caixa eletrônico?","¿Dónde hay un cajero?"],["Com licença, onde fica o banheiro?","Disculpe, ¿dónde está el baño?"],["Tem wi-fi aqui?","¿Hay wifi aquí?"]],"nota":"<b>shopping</b> es la plaza comercial o centro comercial. Ojo: <i>a praça</i> es una plaza pública, al aire libre."},{"tipo":"comparar","titulo":"Largo no es largo","malTitulo":"Parece que significa","mal":"<i>A avenida é muito larga.</i> = la avenida es muy larga<br><i>Largo do Machado</i> = una calle larga","bienTitulo":"En realidad","bien":"<i><b>largo / larga</b></i> = ancho, ancha. «Largo» es <b>comprido</b>: <i>uma rua comprida</i>.<br>En nombres de lugares, <i><b>Largo</b></i> es una plaza pequeña: <i>Largo do Machado</i>, en Río."},{"tipo":"dialogo","titulo":"Diálogo — Una turista mexicana en Salvador de Bahía","lineas":[{"quien":"Daniela","en":"Com licença, moço. Tem uma farmácia aqui perto?","es":"Disculpe, joven. ¿Hay una farmacia cerca?"},{"quien":"Moço","en":"Tem, sim. Fica na próxima rua, do lado da padaria.","es":"Sí hay. Está en la siguiente calle, junto a la panadería."},{"quien":"Daniela","en":"E tem caixa eletrônico?","es":"¿Y hay cajero automático?"},{"quien":"Moço","en":"Aqui não tem. Mas tem um no supermercado, na praça.","es":"Aquí no hay. Pero hay uno en el súper, en la plaza."},{"quien":"Daniela","en":"Muito obrigada!","es":"¡Muchas gracias!"},{"quien":"Moço","en":"De nada. Boa viagem!","es":"De nada. ¡Buen viaje!"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«¿Hay un baño aquí?» (conversación)","ops":["Tem um banheiro aqui?","Hay um banheiro aqui?","É um banheiro aqui?"],"correcta":0},{"p":"Te contestan <i>Não tem.</i> Significa…","ops":["No lo tengo yo.","No hay.","No está abierto."],"correcta":1},{"p":"Un brasileño dice <i>Essa rua é bem larga.</i> La calle es…","ops":["muy larga","muy ancha","muy fea"],"correcta":1},{"p":"Necesitas sacar dinero. Buscas un…","ops":["caixa eletrônico","posto de gasolina","ponto de ônibus"],"correcta":0},{"p":"«La banqueta» se dice…","ops":["a banqueta","a calçada","a praça"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa la pregunta","voz":true,"items":[{"frase":"___ uma padaria aqui perto?","resp":["Tem","Há"],"es":"¿Hay una panadería cerca?"},{"frase":"Onde ___ o ponto de ônibus?","resp":["fica","está"],"es":"¿Dónde está la parada del camión?"},{"frase":"Não ___ wi-fi no quarto.","resp":["tem","há"],"es":"No hay wifi en la habitación."},{"frase":"A farmácia fica na ___.","resp":["esquina"],"es":"La farmacia está en la esquina."}]},{"tipo":"clave","items":["«Hay» en la conversación = <b>tem</b>; formal y escrito = <b>há</b>.","<i>Tem…? — Tem, sim. / Não tem.</i>","<b>Onde fica…?</b> para ubicar un lugar.","<b>largo</b> = ancho; «largo» = <b>comprido</b>."]}],"c-portugues-a1-m4-l2":[{"tipo":"texto","texto":"Las direcciones en portugués se entienden bien si conoces unas diez expresiones. Ojo con una que confunde: <b>direita</b> es derecha (el lado), pero «todo derecho» se dice <b>sempre reto</b> o <b>sempre em frente</b>. El semáforo en Brasil tiene varios nombres: <i>semáforo</i>, <i>sinal</i> y, en São Paulo, <i>farol</i>. Para preguntar si está lejos: <i>É longe?</i>, y si puedes ir caminando: <i>Dá para ir a pé?</i>"},{"tipo":"tabla","titulo":"Indicaciones","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Siga reto. / Siga em frente.","Siga derecho."],["Vire à direita.","Dé vuelta a la derecha."],["Vire à esquerda.","Dé vuelta a la izquierda."],["Na esquina.","En la esquina."],["No sinal / no semáforo.","En el semáforo."],["No final da rua.","Al final de la calle."],["Fica em frente ao banco.","Está enfrente del banco."],["Fica do lado do hotel.","Está al lado del hotel."],["Fica atrás da igreja.","Está detrás de la iglesia."],["É perto. / É longe.","Está cerca. / Está lejos."],["Dá para ir a pé?","¿Se puede ir caminando?"]],"nota":"<i>Siga, vire</i> son formas de usted (para indicar a otro). Entre amigos se oye también <i>segue reto, vira à direita</i>."},{"tipo":"comparar","titulo":"Derecho, derecha y otros calcos","malTitulo":"Evita","mal":"<i>Siga direita.</i> (queriendo decir «siga derecho»)<br><i>Vire a la esquerda.</i><br><i>Fica enfrente do banco.</i>","bienTitulo":"Correcto","bien":"<i>Siga <b>reto</b>.</i> / <i>Siga <b>em frente</b>.</i><br><i>Vire <b>à</b> esquerda.</i> (a + a)<br><i>Fica <b>em frente ao</b> banco.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Un turista brasileño en el centro de Guadalajara","lineas":[{"quien":"Turista","en":"Com licença, onde fica a catedral?","es":"Disculpe, ¿dónde está la catedral?"},{"quien":"Sofía","en":"Fica perto. Siga reto por esta rua até o sinal.","es":"Está cerca. Siga derecho por esta calle hasta el semáforo."},{"quien":"Turista","en":"Até o sinal… e depois?","es":"Hasta el semáforo… ¿y después?"},{"quien":"Sofía","en":"Depois vire à esquerda. A catedral fica em frente à praça.","es":"Después dé vuelta a la izquierda. La catedral está enfrente de la plaza."},{"quien":"Turista","en":"Dá para ir a pé?","es":"¿Se puede ir caminando?"},{"quien":"Sofía","en":"Dá, sim! São uns cinco minutos.","es":"¡Sí! Son como cinco minutos."}]},{"tipo":"practica","rotulo":"Sigue las indicaciones","preguntas":[{"p":"<i>Vire à direita.</i>","ops":["Da vuelta a la derecha.","Sigue derecho.","Da vuelta a la izquierda."],"correcta":0},{"p":"«Siga derecho» se dice…","ops":["Siga direita.","Siga reto.","Siga à direita."],"correcta":1},{"p":"<i>Fica atrás do hotel.</i>","ops":["Está enfrente del hotel.","Está detrás del hotel.","Está dentro del hotel."],"correcta":1},{"p":"En São Paulo te dicen <i>no farol</i>. Es…","ops":["en el faro","en el semáforo","en la esquina"],"correcta":1},{"p":"<i>É longe?</i> significa…","ops":["¿Está lejos?","¿Es largo?","¿Es ancho?"],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma las indicaciones","voz":true,"items":[{"frase":"Siga reto até o final da rua","es":"Siga derecho hasta el final de la calle"},{"frase":"Vire à esquerda no sinal","es":"Dé vuelta a la izquierda en el semáforo"},{"frase":"O banco fica em frente à praça","es":"El banco está enfrente de la plaza"},{"frase":"Dá para ir a pé?","es":"¿Se puede ir caminando?"}]},{"tipo":"pronunciar","rotulo":"Da indicaciones en voz alta","frases":[{"en":"Vire à direita na esquina.","pron":"víri a djiréita na iskína","es":"Dé vuelta a la derecha en la esquina."},{"en":"Siga em frente.","pron":"síga ẽi frẽchi","es":"Siga derecho."},{"en":"Fica do lado da farmácia.","pron":"fíka du ládu da farmásia","es":"Está al lado de la farmacia."},{"en":"É perto, dá para ir a pé.","pron":"é pértu, dá pra ir a pé","es":"Está cerca, se puede ir caminando."}]},{"tipo":"clave","items":["<b>direita</b> = derecha · <b>esquerda</b> = izquierda · <b>reto / em frente</b> = derecho.","<i>Vire <b>à</b> direita</i>: siempre con <b>à</b>.","<i>em frente a, do lado de, atrás de, na esquina, no sinal</i>.","<i>É longe? Dá para ir a pé?</i>"]}],"c-portugues-a1-m4-l3":[{"tipo":"texto","texto":"Atención, mexicano: en Brasil el camión de pasajeros es el <b>ônibus</b>. Si dices que vas a tomar el <i>caminhão</i>, van a imaginarte arriba de un tráiler de carga. Los verbos clave son <b>pegar</b> (tomar un transporte), <b>descer</b> (bajarse) y <b>subir</b> (subirse). Para decir cómo vas, se usa <b>de</b>: <i>de ônibus, de metrô, de carro</i>, pero <b>a pé</b> (caminando). La central de autobuses se llama <b>rodoviária</b>."},{"tipo":"tabla","titulo":"Medios de transporte","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["o ônibus","el camión, el autobús"],["o metrô","el metro"],["o trem","el tren"],["o táxi","el taxi"],["o carro de aplicativo","el auto por aplicación"],["o avião","el avión"],["a rodoviária","la central de autobuses"],["a passagem","el boleto, el pasaje"],["Vou de ônibus. / Vou a pé.","Voy en camión. / Voy caminando."]]},{"tipo":"tabla","titulo":"Frases para moverte","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Qual ônibus vai para Copacabana?","¿Qué camión va a Copacabana?"],["Quanto custa a passagem?","¿Cuánto cuesta el pasaje?"],["Onde eu compro o bilhete?","¿Dónde compro el boleto?"],["Onde eu desço?","¿Dónde me bajo?"],["Vou descer no próximo ponto.","Me voy a bajar en la siguiente parada."],["Moço, me avisa quando chegar?","Joven, ¿me avisa cuando lleguemos?"]]},{"tipo":"comparar","titulo":"Falsos amigos del transporte","malTitulo":"Parece que significa","mal":"<i>caminhão</i> = camión (de pasajeros)<br><i>Vou de camión.</i><br><i>Vou baixar aqui.</i>","bienTitulo":"En realidad","bien":"<i><b>caminhão</b></i> = camión de carga, tráiler. El de pasajeros es el <b>ônibus</b>.<br><i>Vou de <b>ônibus</b>.</i><br><i>Vou <b>descer</b> aqui.</i> (<i>baixar</i> es bajar algo, como un archivo)"},{"tipo":"dialogo","titulo":"Diálogo — En el metro de São Paulo","lineas":[{"quien":"Jorge","en":"Com licença, qual linha vai para a Avenida Paulista?","es":"Disculpe, ¿qué línea va a la Avenida Paulista?"},{"quien":"Funcionária","en":"A linha verde. Você pega aqui e desce na estação Trianon-Masp.","es":"La línea verde. La tomas aquí y te bajas en la estación Trianon-Masp."},{"quien":"Jorge","en":"E onde eu compro o bilhete?","es":"¿Y dónde compro el boleto?"},{"quien":"Funcionária","en":"Ali na bilheteria ou na máquina. Também pode pagar com o cartão.","es":"Ahí en la taquilla o en la máquina. También puedes pagar con la tarjeta."},{"quien":"Jorge","en":"É longe?","es":"¿Está lejos?"},{"quien":"Funcionária","en":"Não, são só quatro estações.","es":"No, son solo cuatro estaciones."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Voy al trabajo en camión.»","ops":["Vou ao trabalho de caminhão.","Vou ao trabalho de ônibus.","Vou ao trabalho em camión."],"correcta":1},{"p":"«¿Dónde me bajo?»","ops":["Onde eu baixo?","Onde eu desço?","Onde eu subo?"],"correcta":1},{"p":"Para viajar de São Paulo a Río en autobús, vas a la…","ops":["rodoviária","estação de metrô","padaria"],"correcta":0},{"p":"«Voy caminando»","ops":["Vou de pé.","Vou a pé.","Vou caminhão."],"correcta":1},{"p":"<i>a passagem</i> es…","ops":["el pasillo","el boleto o pasaje","la pasajera"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Eu vou ___ metrô.","resp":["de"],"es":"Voy en metro."},{"frase":"Qual ônibus ___ para o aeroporto?","resp":["vai"],"es":"¿Qué camión va al aeropuerto?"},{"frase":"Vou ___ no próximo ponto.","resp":["descer"],"es":"Me bajo en la siguiente parada."},{"frase":"Quanto custa a ___?","resp":["passagem"],"es":"¿Cuánto cuesta el pasaje?"},{"frase":"Eu ___ o ônibus às sete.","resp":["pego"],"es":"Tomo el camión a las siete."}]},{"tipo":"clave","items":["Camión de pasajeros = <b>ônibus</b>; <b>caminhão</b> = camión de carga.","<b>pegar</b> (tomar), <b>descer</b> (bajarse), <b>subir</b> (subirse).","<i>de ônibus, de metrô</i>, pero <b>a pé</b>.","<i>Onde eu desço? Quanto custa a passagem?</i>"]}],"c-portugues-a1-m4-l4":[{"tipo":"texto","texto":"La <b>feira</b> es el mercado sobre ruedas brasileño: se pone un día fijo en la calle, con frutas, verduras y el famoso <i>pastel de feira</i> (una empanada frita) con jugo de caña. La moneda es el <b>real</b>, en plural <b>reais</b>, y se escribe <b>R$</b>. Los precios usan coma para los centavos: <i>R$ 12,50</i> se lee <i>doze reais e cinquenta (centavos)</i>. En Brasil casi todos pagan con <b>Pix</b>, una transferencia instantánea con el celular; también se usa mucho el <b>cartão</b> (tarjeta) y el <b>dinheiro</b> (efectivo)."},{"tipo":"tabla","titulo":"Comprar y pagar","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Quanto custa? / Quanto é?","¿Cuánto cuesta? / ¿Cuánto es?"],["Me vê um quilo de tomate, por favor.","Deme un kilo de jitomate, por favor."],["Meio quilo de uva.","Medio kilo de uvas."],["Uma dúzia de ovos.","Una docena de huevos."],["Dá dez reais e cinquenta.","Son diez reales con cincuenta."],["Está caro! Tem desconto?","¡Está caro! ¿Hay descuento?"],["Aceita cartão?","¿Acepta tarjeta?"],["No débito ou no crédito?","¿Débito o crédito?"],["Posso pagar no Pix?","¿Puedo pagar con Pix?"],["Aqui está o seu troco.","Aquí está su cambio."]],"nota":"<i>Me vê…</i> (literalmente «me ve») es la forma más común de pedir en un mostrador o en la feira. <b>troco</b> = el cambio que te regresan."},{"tipo":"comparar","titulo":"Falsos amigos del súper","malTitulo":"Parece que significa","mal":"<i>polvo</i> = polvo<br><i>presunto</i> = presunto sospechoso<br><i>pastel</i> = pastel<br><i>salsa</i> = salsa<br><i>abacaxi</i> = aguacate<br><i>borracha</i> = borracha","bienTitulo":"En realidad","bien":"<i><b>polvo</b></i> = pulpo; el polvo es <b>pó</b><br><i><b>presunto</b></i> = jamón<br><i><b>pastel</b></i> = empanada frita; el pastel es <b>bolo</b><br><i><b>salsa</b></i> = perejil; la salsa es <b>molho</b><br><i><b>abacaxi</b></i> = piña; el aguacate es <b>abacate</b><br><i><b>borracha</b></i> = goma de borrar (en papelería); borracha es <b>bêbada</b>"},{"tipo":"dialogo","titulo":"Diálogo — En la feira de un barrio de São Paulo","lineas":[{"quien":"Feirante","en":"Olha a manga! Manga docinha, freguesa!","es":"¡Mire el mango! ¡Mango dulcecito, marchanta!"},{"quien":"Gabriela","en":"Quanto custa o quilo da manga?","es":"¿A cómo el kilo de mango?"},{"quien":"Feirante","en":"Oito reais o quilo.","es":"Ocho reales el kilo."},{"quien":"Gabriela","en":"Me vê um quilo de manga e um abacaxi, por favor.","es":"Deme un kilo de mango y una piña, por favor."},{"quien":"Feirante","en":"Dá dezoito e cinquenta. Vai pagar como?","es":"Son dieciocho con cincuenta. ¿Cómo va a pagar?"},{"quien":"Gabriela","en":"Posso pagar no Pix?","es":"¿Puedo pagar con Pix?"},{"quien":"Feirante","en":"Pode, sim! A chave está aqui na plaquinha.","es":"¡Claro! La clave está aquí en el letrerito."}]},{"tipo":"tarjetas","rotulo":"Frutas y comida","voz":true,"vozEn":"reverso","instruccion":"Ves la palabra en español; dila en portugués antes de voltear. Cuidado con las trampas.","tarjetas":[{"frente":"la piña","reverso":"o abacaxi","ej":"Um suco de abacaxi, por favor."},{"frente":"el aguacate","reverso":"o abacate","ej":"No Brasil, o abacate se come com açúcar."},{"frente":"la papaya","reverso":"o mamão","ej":"Mamão no café da manhã."},{"frente":"la fresa","reverso":"o morango","ej":"Um quilo de morango."},{"frente":"el limón","reverso":"o limão","ej":"Uma caipirinha de limão."},{"frente":"el jamón","reverso":"o presunto","ej":"Um sanduíche de presunto e queijo."},{"frente":"el pulpo","reverso":"o polvo","ej":"Arroz de polvo."},{"frente":"el pastel (de cumpleaños)","reverso":"o bolo","ej":"Bolo de chocolate."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"<i>R$ 25,90</i> se lee…","ops":["vinte e cinco reais e noventa","vinte e cinco reales noventa","vinte cinco real e nove"],"correcta":0},{"p":"Quieres un pastel de cumpleaños. Pides un…","ops":["pastel","bolo","presunto"],"correcta":1},{"p":"En un menú dice <i>salada de polvo</i>. Es una ensalada de…","ops":["pulpo","pollo","polvo de chile"],"correcta":0},{"p":"«¿Acepta tarjeta?»","ops":["Aceita cartão?","Aceita carta?","Aceita tarjeta?"],"correcta":0},{"p":"El vendedor dice <i>Aqui está o seu troco.</i> Te da…","ops":["tu bolsa","tu cambio","tu recibo"],"correcta":1}]},{"tipo":"clave","items":["<i>Quanto custa? / Quanto é? / Me vê um quilo de…</i>","<b>R$ 12,50</b> = doze reais e cinquenta. Plural: <b>reais</b>.","Pagos: <b>dinheiro</b> (efectivo), <b>cartão</b>, <b>Pix</b>; <b>troco</b> = cambio.","<b>polvo</b> = pulpo · <b>presunto</b> = jamón · <b>abacaxi</b> = piña · <b>borracha</b> = goma."]}],"c-portugues-a1-m4-l5":[{"tipo":"texto","texto":"Para hablar del futuro cercano, el portugués hace lo mismo que el español: <b>ir + infinitivo</b>. Pero con una diferencia que se te va a escapar muchas veces: <b>no lleva «a»</b>. En español: «voy <b>a</b> comprar»; en portugués: <i>Vou comprar</i>. El verbo <b>ir</b> en presente es: <i>eu vou, você vai, a gente vai, nós vamos, vocês vão, eles vão</i>. Y cuando vas a un lugar: <i>Vou <b>ao</b> mercado</i>, <i>Vou <b>à</b> praia</i>, y a tu casa: <i>Vou <b>para</b> casa</i>. En la conversación se oye mucho <i>pra</i> (de <i>para</i>) y <i>no</i>: <i>Vou pra praia, vou no mercado</i>."},{"tipo":"tabla","titulo":"Ir en presente","voz":true,"colVoz":0,"encabezados":["Portugués","Se lee aprox.","Español"],"filas":[["eu vou","éu vôu","yo voy"],["você / ele / ela vai","vosê / éli / éla vai","tú vas / él, ella va"],["a gente vai","a yẽchi vai","nosotros vamos (informal)"],["nós vamos","nós vãmus","nosotros vamos"],["vocês / eles / elas vão","vosês / élis / élas vãu","ustedes / ellos van"]]},{"tipo":"tabla","titulo":"Planes","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Amanhã eu vou comprar as passagens.","Mañana voy a comprar los boletos."],["O que você vai fazer no fim de semana?","¿Qué vas a hacer el fin de semana?"],["A gente vai almoçar fora.","Vamos a comer fuera."],["Vamos pegar o metrô?","¿Tomamos el metro?"],["Eles vão viajar em dezembro.","Ellos van a viajar en diciembre."],["Não vou trabalhar no sábado.","No voy a trabajar el sábado."]]},{"tipo":"comparar","titulo":"Sin la «a» del español","malTitulo":"Evita","mal":"<i>Vou a comprar pão.</i><br><i>Vamos a jantar juntos?</i><br><i>Ela vai a viajar amanhã.</i>","bienTitulo":"Correcto","bien":"<i>Vou <b>comprar</b> pão.</i><br><i>Vamos <b>jantar</b> juntos?</i><br><i>Ela vai <b>viajar</b> amanhã.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Planes para el sábado en São Paulo","lineas":[{"quien":"Renata","en":"O que você vai fazer no sábado, Héctor?","es":"¿Qué vas a hacer el sábado, Héctor?"},{"quien":"Héctor","en":"De manhã vou à feira. Quero provar o pastel com caldo de cana.","es":"En la mañana voy a la feria. Quiero probar el pastel con jugo de caña."},{"quien":"Renata","en":"Boa! E depois?","es":"¡Buena idea! ¿Y después?"},{"quien":"Héctor","en":"Depois vou almoçar na Liberdade e vou visitar o Masp.","es":"Después voy a comer en Liberdade y voy a visitar el Masp."},{"quien":"Renata","en":"Que legal! A gente vai ao Ibirapuera à tarde. Quer ir com a gente?","es":"¡Qué padre! Nosotros vamos a Ibirapuera en la tarde. ¿Quieres venir?"},{"quien":"Héctor","en":"Quero, sim! Vamos pegar o metrô juntos?","es":"¡Claro que sí! ¿Tomamos el metro juntos?"}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"«Voy a llamar a mi mamá.»","ops":["Vou a ligar para a minha mãe.","Vou ligar para a minha mãe.","Vou ligo para a minha mãe."],"correcta":1,"explica":"<b>ligar</b> = llamar por teléfono. Y sin «a»: <i>vou ligar</i>."},{"p":"Nós ___ viajar em julho.","ops":["vamos","vão","vai"],"correcta":0},{"p":"«Me voy a la casa.»","ops":["Vou à casa.","Vou para casa.","Vou a la casa."],"correcta":1},{"p":"Vocês ___ jantar com a gente?","ops":["vai","vão","vamos"],"correcta":1},{"p":"«No voy a trabajar mañana.»","ops":["Não vou trabalhar amanhã.","Vou não trabalhar amanhã.","Não vou a trabalhar amanhã."],"correcta":0}]},{"tipo":"completar","rotulo":"Completa tus planes","voz":true,"items":[{"frase":"Amanhã eu ___ comprar os ingressos.","resp":["vou"],"es":"Mañana voy a comprar las entradas."},{"frase":"A gente ___ almoçar na praia.","resp":["vai"],"es":"Vamos a comer en la playa."},{"frase":"Eles vão ___ o ônibus das oito.","resp":["pegar"],"es":"Van a tomar el camión de las ocho."},{"frase":"Você vai ___ mercado hoje?","resp":["ao","no"],"es":"¿Vas a ir al mercado hoy?"}]},{"tipo":"clave","items":["<b>ir</b>: <i>vou, vai, vamos, vão</i>.","Futuro cercano: <b>ir + infinitivo</b>, sin «a»: <i>Vou comprar</i>.","<i>Vou ao mercado, vou à praia, vou para casa</i>.","<b>ligar</b> = llamar por teléfono. Pasa a la evaluación: necesitas 80%."]}],"c-portugues-a1-m4-pr":[{"tipo":"destacado","texto":"<b>Caso: la tienda de Lupita</b><br>Lupita atiende una tienda de artesanías en San Miguel de Allende. Un sábado entran Fernanda y Gustavo, una pareja de Curitiba que viaja por el Bajío. Hablan poco español, pero se nota que quieren comprar. Lupita decide atenderlos en portugués con lo que ya sabe: saludo, <i>tem</i>, números, <i>fica</i> y frases de cortesía. En esta práctica te pones en su lugar."},{"tipo":"vocabulario","rotulo":"Palabras de la tienda","palabras":[{"en":"o preço","es":"el precio","ej":"Qual é o preço deste prato?"},{"en":"barato / caro","es":"barato / caro","ej":"Este colar é barato."},{"en":"o cartão","es":"la tarjeta","ej":"Aceitamos cartão de crédito."},{"en":"o troco","es":"el cambio (dinero que se devuelve)","ej":"Aqui está o seu troco."},{"en":"a sacola","es":"la bolsa (de compras)","ej":"Quer uma sacola?"},{"en":"o desconto","es":"el descuento","ej":"Tem desconto à vista?"},{"en":"experimentar","es":"probarse (ropa, zapatos)","ej":"Posso experimentar?"},{"en":"o caixa","es":"la caja (donde se paga)","ej":"O caixa fica ali."}]},{"tipo":"dialogo","titulo":"Diálogo — Una tienda de artesanías en San Miguel de Allende","lineas":[{"quien":"Lupita","en":"Boa tarde! Posso ajudar?","es":"¡Buenas tardes! ¿Les ayudo?"},{"quien":"Fernanda","en":"Boa tarde! Quanto custa este prato de cerâmica?","es":"¡Buenas tardes! ¿Cuánto cuesta este plato de cerámica?"},{"quien":"Lupita","en":"Custa quatrocentos pesos. Tem também este menor, de duzentos e cinquenta.","es":"Cuesta cuatrocientos pesos. También está este más chico, de doscientos cincuenta."},{"quien":"Fernanda","en":"Que lindo! Vou levar os dois. Vocês aceitam cartão?","es":"¡Qué bonito! Me llevo los dos. ¿Aceptan tarjeta?"},{"quien":"Lupita","en":"Aceitamos, sim. Débito ou crédito?","es":"Sí, aceptamos. ¿Débito o crédito?"},{"quien":"Gustavo","en":"Crédito. Com licença, tem uma farmácia aqui perto?","es":"Crédito. Disculpe, ¿hay una farmacia cerca?"},{"quien":"Lupita","en":"Tem, sim. Fica na esquina, do lado do banco. Dá pra ir a pé.","es":"Sí, hay. Está en la esquina, junto al banco. Se puede ir caminando."},{"quien":"Fernanda","en":"Muito obrigada! Até logo.","es":"¡Muchas gracias! Hasta luego."},{"quien":"Lupita","en":"De nada! Boa viagem!","es":"¡De nada! ¡Buen viaje!"}]},{"tipo":"practica","rotulo":"¿Entendiste la venta?","preguntas":[{"p":"¿Cuánto cuesta el plato más chico?","ops":["Cuatrocientos pesos","Doscientos cincuenta pesos","Cincuenta pesos"],"correcta":1,"explica":"<i>duzentos e cinquenta</i> = 250."},{"p":"<i>Vou levar os dois</i> significa…","ops":["Me llevo los dos","Voy a llevar a los dos niños","Vuelvo en dos horas"],"correcta":0,"explica":"<b>levar</b> en una tienda = llevarse, comprar."},{"p":"Un cliente te pregunta <i>Tem desconto?</i> Te está pidiendo…","ops":["el cambio","una bolsa","un descuento"],"correcta":2},{"p":"Para decir «Sí, aceptamos tarjeta», Lupita dice…","ops":["Aceitamos, sim.","Sim, aceptamos tarjeta.","Tem cartão, sim."],"correcta":0,"explica":"En Brasil se contesta repitiendo el verbo: <i>Aceitamos, sim</i>, <i>Tem, sim</i>."}]},{"tipo":"relacionar","rotulo":"Relaciona la palabra con su significado","voz":true,"pares":[["o troco","el cambio (dinero)"],["a sacola","la bolsa de compras"],["o caixa","la caja para pagar"],["o desconto","el descuento"],["experimentar","probarse ropa"],["o cartão","la tarjeta"]]},{"tipo":"completar","rotulo":"Completa lo que dice Lupita","voz":true,"items":[{"frase":"Este colar ___ trezentos pesos.","resp":["custa"],"es":"Este collar cuesta trescientos pesos."},{"frase":"Aceitamos cartão de ___ e de débito.","resp":["crédito","credito"],"es":"Aceptamos tarjeta de crédito y de débito."},{"frase":"A farmácia ___ na esquina.","resp":["fica","está"],"es":"La farmacia está en la esquina."},{"frase":"Aqui está o seu ___.","resp":["troco"],"es":"Aquí está su cambio."},{"frase":"Quer uma ___?","resp":["sacola"],"es":"¿Quiere una bolsa?"}]},{"tipo":"escuchar","rotulo":"Escucha lo que dicen los clientes","frases":[{"en":"Tem em outro tamanho?","pron":"tẽi ẽi ôutru tamáñu","es":"¿Lo hay en otra talla?"},{"en":"Posso experimentar?","pron":"pósu isperimẽtár","es":"¿Me lo puedo probar?"},{"en":"Está muito caro. Tem desconto?","pron":"istá mũintu káru. tẽi djiskõtu","es":"Está muy caro. ¿Hay descuento?"},{"en":"Vou levar este.","pron":"vôu levár éschi","es":"Me llevo este."},{"en":"Onde fica o caixa?","pron":"õdji fíka u káisha","es":"¿Dónde está la caja?"}]},{"tipo":"pronunciar","rotulo":"Atiende en voz alta","frases":[{"en":"Boa tarde! Posso ajudar?","pron":"bóa tárdji! pósu ayudár","es":"¡Buenas tardes! ¿Le ayudo?"},{"en":"Custa quatrocentos pesos.","pron":"kústa kwatrusẽtus pézus","es":"Cuesta cuatrocientos pesos."},{"en":"Aceitamos cartão de crédito.","pron":"aseitãmus kartãu dji krédjitu","es":"Aceptamos tarjeta de crédito."},{"en":"Aqui está o seu troco.","pron":"akí istá u séu trôku","es":"Aquí está su cambio."},{"en":"Muito obrigada e boa viagem!","pron":"mũintu obrigáda i bóa viáyẽi","es":"¡Muchas gracias y buen viaje!"}]},{"tipo":"ordenar","rotulo":"Arma las frases de la venta","voz":true,"items":[{"frase":"Este prato custa quatrocentos pesos","es":"Este plato cuesta cuatrocientos pesos"},{"frase":"Tem uma farmácia aqui perto?","es":"¿Hay una farmacia cerca?"},{"frase":"Vou levar os dois, obrigada","es":"Me llevo los dos, gracias"}]},{"tipo":"reflexion","rotulo":"Tu propia venta","pregunta":"Imagina que clientes brasileños entran a tu negocio (o a uno que conozcas). Escribe en portugués cinco frases: el saludo, el precio de dos productos en pesos, cómo pueden pagar, dónde queda un lugar cercano y la despedida. Luego léelas en voz alta cuidando las nasales de <i>cartão</i> y el «dji» de <i>de</i>.","ayuda":"Boa tarde! Posso ajudar? / … custa … pesos. / Aceitamos… / A farmácia fica… / Obrigada e boa viagem!"},{"tipo":"clave","items":["Precios: <i>Quanto custa? — Custa … pesos</i>.","Contesta repitiendo el verbo: <i>Aceitamos, sim. Tem, sim</i>.","<b>troco</b> = cambio · <b>sacola</b> = bolsa · <b>caixa</b> = caja · <b>experimentar</b> = probarse."]}],"c-portugues-a1-m5-l1":[{"tipo":"texto","texto":"Para pedir algo con amabilidad, los brasileños casi nunca dicen <i>eu quero</i> (quiero), que suena exigente. Usan dos fórmulas: <b>Eu queria…</b> (literalmente «yo quería») y <b>Eu gostaria de…</b> (me gustaría). Las dos equivalen a nuestro «quisiera». Otra muy común es preguntar con <b>Pode…?</b>: <i>Pode me dar mais uma toalha?</i> (¿Me puede dar otra toalla?). En Brasil la habitación de hotel es el <b>quarto</b>, y el baño, el <b>banheiro</b>."},{"tipo":"tabla","titulo":"Frases de hotel","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Eu tenho uma reserva em nome de Reyes.","Tengo una reservación a nombre de Reyes."],["Eu queria um quarto para duas pessoas.","Quisiera una habitación para dos personas."],["Eu gostaria de fazer o check-in.","Me gustaría hacer el check-in."],["O café da manhã está incluído?","¿El desayuno está incluido?"],["Qual é a senha do wi-fi?","¿Cuál es la contraseña del wifi?"],["Pode me dar mais uma toalha?","¿Me puede dar otra toalla?"],["O ar-condicionado não está funcionando.","El aire acondicionado no funciona."],["O chuveiro não esquenta.","La regadera no calienta."],["Posso deixar a mala aqui?","¿Puedo dejar la maleta aquí?"],["A que horas é o check-out?","¿A qué hora es la salida?"]]},{"tipo":"comparar","titulo":"Eu quero suena a orden","malTitulo":"Evita","mal":"<i>Eu quero um quarto.</i><br><i>Me dá a chave.</i> (con tono seco)","bienTitulo":"Correcto","bien":"<i><b>Eu queria</b> um quarto, por favor.</i><br><i><b>Eu gostaria de</b> um quarto com vista para o mar.</i><br><i><b>Pode me dar</b> a chave, por favor?</i>"},{"tipo":"comparar","titulo":"Falsos amigos del cuarto de hotel","malTitulo":"Parece que significa","mal":"<i>almofada</i> = almohada<br><i>vaso</i> = vaso<br><i>cobertor</i> = cubrecama","bienTitulo":"En realidad","bien":"<i><b>almofada</b></i> = cojín; la almohada es el <b>travesseiro</b><br><i><b>vaso</b></i> = maceta o el inodoro (<i>vaso sanitário</i>); el vaso para beber es el <b>copo</b><br><i><b>cobertor</b></i> = cobija"},{"tipo":"dialogo","titulo":"Diálogo — Check-in en un hotel de Copacabana","lineas":[{"quien":"Recepcionista","en":"Boa noite! Bem-vinda ao Rio!","es":"¡Buenas noches! ¡Bienvenida a Río!"},{"quien":"Mónica","en":"Boa noite! Eu tenho uma reserva em nome de Mónica Reyes.","es":"¡Buenas noches! Tengo una reservación a nombre de Mónica Reyes."},{"quien":"Recepcionista","en":"Só um momento… Isso: quarto individual, quatro noites. Seu passaporte, por favor.","es":"Un momento… Así es: habitación sencilla, cuatro noches. Su pasaporte, por favor."},{"quien":"Mónica","en":"Aqui está. O café da manhã está incluído?","es":"Aquí tiene. ¿El desayuno está incluido?"},{"quien":"Recepcionista","en":"Está, sim. É servido das seis às dez, no térreo.","es":"Sí. Se sirve de seis a diez, en la planta baja."},{"quien":"Mónica","en":"Ótimo. E eu queria um travesseiro a mais, por favor.","es":"Perfecto. Y quisiera una almohada extra, por favor."},{"quien":"Recepcionista","en":"Claro! Vou mandar para o seu quarto. É o 512, no quinto andar.","es":"¡Claro! La mando a su habitación. Es la 512, en el quinto piso."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Quieres una habitación. Lo más amable es…","ops":["Eu quero um quarto.","Eu queria um quarto, por favor.","Um quarto, rápido."],"correcta":1},{"p":"Necesitas otra almohada. Pides un…","ops":["travesseiro","almofada","cobertor"],"correcta":0},{"p":"«La regadera no calienta.»","ops":["O chuveiro não esquenta.","A regadeira não esquenta.","O banheiro não está quente."],"correcta":0},{"p":"<i>no térreo</i> significa…","ops":["en la terraza","en la planta baja","en el sótano"],"correcta":1},{"p":"Pides agua para tomar en el cuarto: <i>Pode me dar um ___ de água?</i>","ops":["vaso","copo","pote"],"correcta":1}]},{"tipo":"pronunciar","rotulo":"Dilo en la recepción","frases":[{"en":"Eu tenho uma reserva em nome de Reyes.","pron":"éu tẽñu úma jezérva ẽi nõmi dji jéies","es":"Tengo una reservación a nombre de Reyes."},{"en":"Eu gostaria de fazer o check-in.","pron":"éu gostaría dji fazér u shekín","es":"Me gustaría hacer el check-in."},{"en":"Pode me dar mais uma toalha?","pron":"pódji mi dar máis úma toália","es":"¿Me puede dar otra toalla?"},{"en":"O ar-condicionado não está funcionando.","pron":"u ar kõdjisionádu nãu istá fũsionãdu","es":"El aire acondicionado no funciona."}]},{"tipo":"clave","items":["Para pedir con cortesía: <b>Eu queria…</b>, <b>Eu gostaria de…</b>, <b>Pode…?</b>","<b>quarto</b> = habitación · <b>banheiro</b> = baño · <b>chuveiro</b> = regadera.","<b>travesseiro</b> = almohada · <b>almofada</b> = cojín.","<b>copo</b> = vaso para beber · <b>vaso</b> = maceta o inodoro."]}],"c-portugues-a1-m5-l2":[{"tipo":"texto","texto":"En Brasil vas a encontrar tres tipos de lugares para comer: el <b>restaurante a la carta</b>, el <b>restaurante por quilo</b> (te sirves en bufé y pagas según lo que pesa tu plato; ideal para la comida del mediodía) y el <b>prato feito</b> o <i>PF</i> (la comida corrida: arroz, frijol, carne y ensalada). El mesero es el <b>garçom</b>, el menú es el <b>cardápio</b> y la cuenta, <b>a conta</b>. Muchos restaurantes agregan <b>10% de serviço</b> a la cuenta; esa es la propina, que en portugués se dice <b>gorjeta</b>."},{"tipo":"tabla","titulo":"Platos y bebidas brasileños","voz":true,"colVoz":0,"encabezados":["Portugués","Qué es"],"filas":[["a feijoada","Frijoles negros con carne de cerdo, con arroz, farofa, col y naranja"],["o pão de queijo","Bolitas de pan de yuca con queso"],["a coxinha","Croqueta de pollo en forma de gota"],["a moqueca","Guiso de pescado con leche de coco y aceite de dendê"],["o churrasco","Carnes asadas; en la <i>churrascaria</i> te las sirven sin límite"],["o açaí","Pulpa congelada de açaí, con plátano y granola"],["o brigadeiro","Dulce de chocolate y leche condensada"],["o guaraná","Refresco de guaraná"],["a caipirinha","Coctel de cachaça con limón y azúcar"]]},{"tipo":"tabla","titulo":"Frases del restaurante","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Mesa para dois, por favor.","Mesa para dos, por favor."],["Pode me trazer o cardápio?","¿Me puede traer la carta?"],["Eu queria uma moqueca.","Quisiera una moqueca."],["Para mim, um suco de maracujá.","Para mí, un jugo de maracuyá."],["Água com gás ou sem gás?","¿Agua mineral o natural?"],["Sem gelo, por favor.","Sin hielo, por favor."],["Estava delicioso!","¡Estuvo delicioso!"],["A conta, por favor.","La cuenta, por favor."],["O serviço está incluído?","¿El servicio está incluido?"]]},{"tipo":"comparar","titulo":"Falsos amigos de la mesa","malTitulo":"Parece que significa","mal":"<i>propina</i> = propina para el mesero<br><i>sobremesa</i> = la plática después de comer<br><i>garrafa</i> = garrafa de agua<br><i>exquisito</i> para elogiar la comida","bienTitulo":"En realidad","bien":"<i><b>propina</b></i> = soborno; la propina es <b>gorjeta</b> (o los 10% de <i>serviço</i>)<br><i><b>sobremesa</b></i> = postre<br><i><b>garrafa</b></i> = botella: <i>uma garrafa de água</i><br>Se dice <b>delicioso</b> o <b>uma delícia</b>; <i>esquisito</i> es «raro»"},{"tipo":"dialogo","titulo":"Diálogo — Un restaurante en Botafogo, Río","lineas":[{"quien":"Garçom","en":"Boa noite! Mesa para quantos?","es":"¡Buenas noches! ¿Mesa para cuántos?"},{"quien":"Luis","en":"Para dois, por favor. Pode me trazer o cardápio?","es":"Para dos, por favor. ¿Me puede traer la carta?"},{"quien":"Garçom","en":"Claro. Hoje tem feijoada, é o prato do dia.","es":"Claro. Hoy hay feijoada, es el plato del día."},{"quien":"Luis","en":"Eu queria uma feijoada, então. E para ela, uma moqueca.","es":"Entonces quisiera una feijoada. Y para ella, una moqueca."},{"quien":"Garçom","en":"E para beber?","es":"¿Y de tomar?"},{"quien":"Paty","en":"Para mim, um suco de maracujá sem açúcar. E uma garrafa de água sem gás.","es":"Para mí, un jugo de maracuyá sin azúcar. Y una botella de agua natural."},{"quien":"Luis","en":"Com licença! Estava uma delícia. A conta, por favor. O serviço está incluído?","es":"¡Disculpe! Estuvo delicioso. La cuenta, por favor. ¿El servicio está incluido?"},{"quien":"Garçom","en":"Está, sim: dez por cento. Débito ou crédito?","es":"Sí: diez por ciento. ¿Débito o crédito?"}]},{"tipo":"relacionar","rotulo":"Relaciona cada plato","voz":true,"pares":[["pão de queijo","bolitas de pan con queso"],["coxinha","croqueta de pollo"],["feijoada","frijoles negros con carne de cerdo"],["sobremesa","postre"],["gorjeta","propina"],["cardápio","menú, carta"]]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Quieres dejar propina al mesero. Le dejas una…","ops":["propina","gorjeta","sobremesa"],"correcta":1,"explica":"<b>propina</b> en portugués es un soborno. ¡Cuidado!"},{"p":"El mesero pregunta <i>E de sobremesa?</i> Te está ofreciendo…","ops":["café para platicar","postre","otra bebida"],"correcta":1},{"p":"En un <i>restaurante por quilo</i>…","ops":["pagas según el peso de tu plato","todo cuesta un kilo de reales","solo venden carne"],"correcta":0},{"p":"«Quisiera un jugo de naranja.»","ops":["Eu queria um suco de laranja.","Eu quero um jugo de naranja.","Eu gostaria um suco de laranja."],"correcta":0,"explica":"Con <i>gostaria</i> se necesita <b>de</b>: <i>Eu gostaria de um suco</i>."},{"p":"<i>Água com gás</i> es…","ops":["agua mineral (con burbujas)","agua con gas LP","agua caliente"],"correcta":0}]},{"tipo":"clave","items":["<b>garçom</b>, <b>cardápio</b>, <b>a conta</b>; <i>restaurante por quilo</i> y <i>prato feito</i>.","Pide con <i>Eu queria… / Para mim…</i>","<b>gorjeta</b> = propina; <b>propina</b> = soborno. Revisa si ya hay 10% de serviço.","<b>sobremesa</b> = postre · <b>garrafa</b> = botella."]}],"c-portugues-a1-m5-l3":[{"tipo":"texto","texto":"El <b>pretérito perfeito</b> es el pasado para acciones terminadas: <i>Ontem eu <b>comi</b> feijoada</i> (Ayer comí feijoada). Para un mexicano es muy fácil, porque se usa igual que nuestro «comí, fui, hice»: <i>Você já <b>almoçou</b>?</i> (¿Ya comiste?). Las terminaciones se parecen mucho a las del español: <b>-ei</b> (falei), <b>-i</b> (comi, abri) para «yo», y <b>-ou, -eu, -iu</b> para «él». Y una buena noticia: <b>ir</b> y <b>ser</b> se conjugan igual que en español en «yo»: <i>eu fui</i>. Palabras útiles: <i>ontem</i> (ayer), <i>anteontem</i> (antier), <i>semana passada</i>, <i>no sábado</i>, <i>já</i> (ya), <i>ainda não</i> (todavía no)."},{"tipo":"tabla","titulo":"Verbos regulares en pasado","voz":true,"colVoz":1,"encabezados":["Persona","falar","comer","abrir"],"filas":[["eu","falei","comi","abri"],["você / ele / ela / a gente","falou","comeu","abriu"],["nós","falamos","comemos","abrimos"],["vocês / eles / elas","falaram","comeram","abriram"]],"nota":"<i>nós falamos</i> y <i>nós comemos</i> son iguales en presente y pasado, como en español: el contexto (<i>ontem, hoje</i>) aclara."},{"tipo":"tabla","titulo":"Irregulares muy usados","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["eu fui · ele foi · nós fomos · eles foram","ir y ser: fui, fue, fuimos, fueron"],["eu tive · ele teve · eles tiveram","tuve, tuvo, tuvieron"],["eu estive · ele esteve · eles estiveram","estuve, estuvo, estuvieron"],["eu fiz · ele fez · eles fizeram","hice, hizo, hicieron"],["eu vi · ele viu · eles viram","vi, vio, vieron"]]},{"tipo":"comparar","titulo":"El pasado «españolizado»","malTitulo":"Evita","mal":"<i>Eu falé com ele.</i><br><i>Ela comió muito.</i><br><i>Eu tuve uma reunião.</i><br><i>Eu hice o check-out.</i>","bienTitulo":"Correcto","bien":"<i>Eu <b>falei</b> com ele.</i><br><i>Ela <b>comeu</b> muito.</i><br><i>Eu <b>tive</b> uma reunião.</i><br><i>Eu <b>fiz</b> o check-out.</i>"},{"tipo":"escuchar","rotulo":"Escucha lo que hizo Mónica en Río","frases":[{"en":"Ontem eu fui à praia de Ipanema.","pron":"õtẽi éu fui a práia dji ipanéma","es":"Ayer fui a la playa de Ipanema."},{"en":"Eu comi pão de queijo e tomei açaí.","pron":"éu komí pãu dji kéiyu i tomêi asaí","es":"Comí pan de queso y tomé açaí."},{"en":"À tarde, a gente visitou o Cristo Redentor.","es":"En la tarde visitamos el Cristo Redentor."},{"en":"Choveu um pouco, mas foi lindo.","pron":"shovéu ũ pôuku, mas foi lĩdu","es":"Llovió un poco, pero estuvo precioso."},{"en":"Eu tirei muitas fotos!","pron":"éu chiréi mũintas fótus","es":"¡Tomé muchas fotos!"}]},{"tipo":"practica","rotulo":"Elige el pasado correcto","preguntas":[{"p":"Ontem eu ___ com o meu chefe.","ops":["falé","falei","falou"],"correcta":1},{"p":"Ela ___ feijoada no sábado.","ops":["comeu","comió","comi"],"correcta":0},{"p":"«Fuimos al centro.»","ops":["Fomos ao centro.","Fuimos ao centro.","Vamos ao centro ontem."],"correcta":0},{"p":"«Hice una reservación.»","ops":["Eu hice uma reserva.","Eu fiz uma reserva.","Eu fez uma reserva."],"correcta":1},{"p":"<i>Você já almoçou? — Ainda não.</i> Significa…","ops":["Sí, ya comí.","Todavía no.","No voy a comer."],"correcta":1}]},{"tipo":"completar","rotulo":"Cuenta tu fin de semana","voz":true,"items":[{"frase":"No sábado eu ___ ao cinema.","resp":["fui"],"es":"El sábado fui al cine."},{"frase":"A gente ___ uma pizza.","resp":["comeu"],"es":"Comimos una pizza."},{"frase":"Eles ___ o museu no domingo.","resp":["visitaram"],"es":"Ellos visitaron el museo el domingo."},{"frase":"Eu ___ muito trabalho ontem.","resp":["tive"],"es":"Ayer tuve mucho trabajo."},{"frase":"Você ___ as fotos?","resp":["viu"],"es":"¿Viste las fotos?"}]},{"tipo":"clave","items":["Regulares: <i>falei, falou · comi, comeu · abri, abriu</i>.","<b>ir/ser</b>: <i>fui, foi, fomos, foram</i> · <b>ter</b>: <i>tive, teve</i> · <b>fazer</b>: <i>fiz, fez</i>.","Se usa como nuestro «comí»: <i>Você já almoçou?</i>","<i>ontem, semana passada, já, ainda não</i>. <b>tirar fotos</b> = tomar fotos."]}],"c-portugues-a1-m5-l4":[{"tipo":"texto","texto":"La familia en portugués se parece a la nuestra, con dos trampas: <b>pais</b> (sin acento) son los padres, mamá y papá, mientras que <b>país</b> es el país; y <b>parentes</b> son todos tus familiares (tíos, primos…), no solo tus padres. Otra: <i>avô</i> (abuelo) y <i>avó</i> (abuela) se distinguen solo por la o, cerrada en <i>avô</i> y abierta en <i>avó</i>. En casa se dice <i>vovô</i> y <i>vovó</i>.<br><br>Para invitar, los brasileños son directos y cálidos: <i>Vamos tomar um café?</i>, <i>Quer ir com a gente?</i> o, muy informal, <i>Bora?</i> (¿Jalas?). Si no puedes, se rechaza con suavidad: <i>Que pena, não posso. Fica para a próxima!</i>"},{"tipo":"tabla","titulo":"La familia","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["o pai · a mãe · os pais","el papá · la mamá · los padres"],["o irmão · a irmã","el hermano · la hermana"],["o filho · a filha","el hijo · la hija"],["o marido · a esposa","el esposo · la esposa"],["o avô · a avó","el abuelo · la abuela"],["o tio · a tia · o primo · a prima","el tío · la tía · el primo · la prima"],["o sobrinho · o neto","el sobrino · el nieto"],["o sogro · a sogra","el suegro · la suegra"],["os parentes","los familiares"]]},{"tipo":"tabla","titulo":"Invitar, aceptar y rechazar","voz":true,"colVoz":0,"encabezados":["Portugués","Español"],"filas":[["Vamos tomar um café?","¿Vamos por un café?"],["Quer ir ao cinema comigo?","¿Quieres ir al cine conmigo?"],["No domingo vai ter churrasco lá em casa.","El domingo va a haber carne asada en mi casa."],["Topa? — Topo!","¿Te late? — ¡Me late!"],["Claro, vamos!","¡Claro, vamos!"],["Que pena, não posso.","Qué lástima, no puedo."],["Fica para a próxima.","Será para la próxima."],["A que horas? Onde?","¿A qué hora? ¿Dónde?"],["Combinado! Posso levar alguma coisa?","¡Quedamos! ¿Llevo algo?"]]},{"tipo":"comparar","titulo":"Falsos amigos de la familia","malTitulo":"Parece que significa","mal":"<i>A minha irmã está embaraçada.</i> = mi hermana está embarazada<br><i>os pais</i> = los países<br><i>os parentes</i> = los padres","bienTitulo":"En realidad","bien":"<i><b>embaraçada</b></i> = apenada, incómoda; embarazada es <b>grávida</b><br><i><b>os pais</b></i> = los padres; los países son <i>os países</i><br><i><b>os parentes</b></i> = los familiares"},{"tipo":"dialogo","titulo":"Diálogo — Una invitación en la planta de Querétaro","lineas":[{"quien":"Rafael","en":"Diego, no domingo vai ter churrasco lá em casa. Topa?","es":"Diego, el domingo va a haber carne asada en mi casa. ¿Te late?"},{"quien":"Diego","en":"Topo! Posso levar a minha esposa e os meus filhos?","es":"¡Me late! ¿Puedo llevar a mi esposa y a mis hijos?"},{"quien":"Rafael","en":"Claro! A minha mãe e a minha irmã também vão. A minha irmã está grávida, vai ter gêmeos!","es":"¡Claro! Mi mamá y mi hermana también van a ir. Mi hermana está embarazada, ¡va a tener gemelos!"},{"quien":"Diego","en":"Que notícia boa! A que horas?","es":"¡Qué buena noticia! ¿A qué hora?"},{"quien":"Rafael","en":"Ao meio-dia.","es":"Al mediodía."},{"quien":"Diego","en":"Combinado! Eu levo a sobremesa.","es":"¡Quedamos! Yo llevo el postre."}]},{"tipo":"practica","rotulo":"Elige la opción correcta","preguntas":[{"p":"Tu amiga dice <i>Estou grávida!</i> Te está diciendo que…","ops":["está enferma","está embarazada","está avergonzada"],"correcta":1},{"p":"<i>Os meus pais moram em Puebla.</i> ¿Quiénes viven en Puebla?","ops":["sus padres","sus familiares","sus países"],"correcta":0},{"p":"La mamá de tu mamá es tu…","ops":["avô","avó","sogra"],"correcta":1},{"p":"Te invitan y no puedes ir. Dices…","ops":["Topo!","Que pena, não posso. Fica para a próxima.","Combinado!"],"correcta":1},{"p":"<i>Topa?</i> significa…","ops":["¿Te late? / ¿Le entras?","¿Chocamos?","¿Topaste?"],"correcta":0}]},{"tipo":"completar","rotulo":"Completa la invitación","voz":true,"items":[{"frase":"Vamos ___ um café depois do trabalho?","resp":["tomar"],"es":"¿Vamos por un café después del trabajo?"},{"frase":"Quer ir ao cinema ___?","resp":["comigo"],"es":"¿Quieres ir al cine conmigo?"},{"frase":"Que pena, não ___.","resp":["posso"],"es":"Qué lástima, no puedo."},{"frase":"A minha ___ é mãe da minha esposa.","resp":["sogra"],"es":"Mi suegra es la mamá de mi esposa."},{"frase":"Fica para a ___!","resp":["próxima","proxima"],"es":"¡Será para la próxima!"}]},{"tipo":"clave","items":["<b>pais</b> = padres · <b>parentes</b> = familiares · <b>avô</b> (abuelo) / <b>avó</b> (abuela).","<b>grávida</b> = embarazada · <b>embaraçada</b> = apenada.","Invitar: <i>Vamos…? Quer…? Topa?</i> Aceptar: <i>Topo! Combinado!</i>","Rechazar: <i>Que pena, não posso. Fica para a próxima.</i>"]}],"c-portugues-a1-m5-l5":[{"tipo":"texto","texto":"Llegó la hora de juntar todo. Mónica, de Guadalajara, pasó cuatro días en <b>Río de Janeiro</b>: se hospedó en Copacabana, subió al <b>Pão de Açúcar</b> y al <b>Cristo Redentor</b>, probó la feijoada y se hizo amiga de Juliana, una carioca (así se les dice a los de la ciudad de Río). Escucha su último día y fíjate en todo lo que ya reconoces: saludos, <i>tem</i>, direcciones, <i>ir</i> + infinitivo, pretérito y una invitación. Al final aparece una palabra que no tiene traducción exacta: <b>saudade</b>, la nostalgia de algo o alguien que extrañas."},{"tipo":"dialogo","titulo":"Diálogo — El último día en Río","lineas":[{"quien":"Juliana","en":"E aí, Mónica! Como foi a viagem?","es":"¡Qué onda, Mónica! ¿Cómo estuvo el viaje?"},{"quien":"Mónica","en":"Foi incrível! Ontem eu subi o Pão de Açúcar e vi o pôr do sol.","es":"¡Increíble! Ayer subí al Pan de Azúcar y vi el atardecer."},{"quien":"Juliana","en":"Que lindo! E você já foi ao Cristo Redentor?","es":"¡Qué bonito! ¿Y ya fuiste al Cristo Redentor?"},{"quien":"Mónica","en":"Fui no sábado. Peguei o trenzinho do Corcovado.","es":"Fui el sábado. Tomé el trenecito del Corcovado."},{"quien":"Juliana","en":"E a comida? Você gostou?","es":"¿Y la comida? ¿Te gustó?"},{"quien":"Mónica","en":"Adorei! Comi feijoada, pão de queijo e tomei muito açaí.","es":"¡Me encantó! Comí feijoada, pan de queso y tomé mucho açaí."},{"quien":"Juliana","en":"Hoje à noite a gente vai jantar em Copacabana. Topa?","es":"Hoy en la noche vamos a cenar en Copacabana. ¿Te late?"},{"quien":"Mónica","en":"Topo! Mas amanhã eu volto para o México… Já estou com saudade!","es":"¡Me late! Pero mañana regreso a México… ¡Ya lo extraño!"},{"quien":"Juliana","en":"Então vamos aproveitar! Te pego no hotel às oito.","es":"¡Entonces a aprovechar! Paso por ti al hotel a las ocho."}]},{"tipo":"practica","rotulo":"¿Entendiste el viaje?","preguntas":[{"p":"¿Qué hizo Mónica ayer?","ops":["Fue al Cristo Redentor.","Subió al Pan de Azúcar y vio el atardecer.","Cenó en Copacabana."],"correcta":1},{"p":"<i>Te pego no hotel às oito</i> significa…","ops":["Te pego en el hotel a las ocho.","Paso por ti al hotel a las ocho.","Te veo en el hotel a las ocho."],"correcta":1,"explica":"<b>pegar</b> alguien = pasar por esa persona, recogerla."},{"p":"<i>Já estou com saudade</i> expresa…","ops":["cansancio","nostalgia, que ya extraña el lugar","hambre"],"correcta":1},{"p":"«¿Cómo estuvo el viaje?»","ops":["Como foi a viagem?","Como estuvo o viagem?","Como é a viagem?"],"correcta":0},{"p":"Para aceptar la invitación, Mónica dice…","ops":["Topa?","Topo!","Fica para a próxima."],"correcta":1},{"p":"Una persona de la ciudad de Río es…","ops":["carioca","paulista","riana"],"correcta":0}]},{"tipo":"escuchar","rotulo":"Escucha frases de todo el curso","frases":[{"en":"Boa tarde! Eu tenho uma reserva em nome de Reyes.","es":"¡Buenas tardes! Tengo una reservación a nombre de Reyes."},{"en":"Com licença, tem um caixa eletrônico aqui perto?","es":"Disculpe, ¿hay un cajero cerca?"},{"en":"Qual ônibus vai para Copacabana?","pron":"kwáu ônibus vai pra kopakabána","es":"¿Qué camión va a Copacabana?"},{"en":"Eu queria uma água sem gás, por favor.","es":"Quisiera un agua natural, por favor."},{"en":"No domingo a gente foi à praia.","es":"El domingo fuimos a la playa."},{"en":"Muito obrigada por tudo! Até a próxima!","pron":"mũintu obrigáda pur túdu! até a prósima","es":"¡Muchas gracias por todo! ¡Hasta la próxima!"}]},{"tipo":"ordenar","rotulo":"Arma las frases del viaje","voz":true,"items":[{"frase":"Ontem eu fui ao Cristo Redentor","es":"Ayer fui al Cristo Redentor"},{"frase":"Eu queria um suco de maracujá, por favor","es":"Quisiera un jugo de maracuyá, por favor"},{"frase":"Amanhã eu vou voltar para o México","es":"Mañana voy a regresar a México"},{"frase":"Hoje à noite a gente vai jantar fora","es":"Hoy en la noche vamos a cenar fuera"}]},{"tipo":"completar","rotulo":"Completa el mensaje de Mónica a Juliana","voz":true,"items":[{"frase":"Oi, Ju! Já ___ no aeroporto.","resp":["estou","tô"],"es":"¡Hola, Ju! Ya estoy en el aeropuerto."},{"frase":"Eu ___ muito a viagem!","resp":["adorei","amei"],"es":"¡Me encantó el viaje!"},{"frase":"Muito obrigada ___ tudo!","resp":["por"],"es":"¡Muchas gracias por todo!"},{"frase":"Já estou com ___ do Rio.","resp":["saudade","saudades"],"es":"Ya extraño Río."}]},{"tipo":"reflexion","rotulo":"Tu viaje en portugués","pregunta":"Imagina que acabas de regresar de un viaje a Río o a São Paulo. Escribe un mensaje de cinco o seis frases a un amigo brasileño: dónde te quedaste, qué lugares visitaste, qué comiste, qué te gustó más y qué vas a hacer la próxima vez. Luego léelo en voz alta cuidando las nasales y el «chi» de <i>noite</i>.","ayuda":"Oi! Eu fiquei num hotel em… Eu fui ao… / à… Eu comi… e tomei… Eu gostei muito de… Na próxima vez eu vou… Já estou com saudade!"},{"tipo":"clave","items":["Pasado: <i>fui, comi, peguei, gostei, adorei</i>. Planes: <i>vou voltar, vamos jantar</i>.","Pedir: <i>Eu queria… Pode…? Tem…?</i>","Invitaciones: <i>Topa? — Topo! Combinado!</i>","<b>saudade</b> = extrañar algo o a alguien. Pasa a la evaluación final del módulo: necesitas 80%."]}],"c-portugues-a1-m5-pr":[{"tipo":"destacado","texto":"<b>Caso: Daniel en la Paulista</b><br>Daniel trabaja en ventas para una empresa de autopartes de Monterrey. Viaja dos días a <b>São Paulo</b> para conocer a Renata, compradora de un cliente brasileño. Llega de noche al hotel, al día siguiente toma un taxi a la <b>Avenida Paulista</b>, tiene la reunión y después comen en un <i>restaurante por quilo</i>. Necesita pedir la <b>nota fiscal</b> (la factura) para comprobar sus gastos."},{"tipo":"vocabulario","rotulo":"Palabras del viaje de trabajo","palabras":[{"en":"o voo","es":"el vuelo","ej":"O voo chegou atrasado."},{"en":"a reunião","es":"la junta, la reunión","ej":"A reunião é às dez."},{"en":"a empresa","es":"la empresa","ej":"Eu trabalho numa empresa de Monterrey."},{"en":"o almoço","es":"la comida del mediodía","ej":"Vamos almoçar juntos?"},{"en":"a nota fiscal","es":"la factura","ej":"Pode me dar a nota fiscal?"},{"en":"o recibo","es":"el recibo, el comprobante","ej":"Preciso do recibo do táxi."},{"en":"Combinado!","es":"¡Quedamos! ¡Trato hecho!","ej":"Amanhã às nove? Combinado!"}]},{"tipo":"dialogo","titulo":"Diálogo — Oficina de un cliente en la Avenida Paulista","lineas":[{"quien":"Renata","en":"Bom dia! Você é o Daniel?","es":"¡Buenos días! ¿Tú eres Daniel?"},{"quien":"Daniel","en":"Sou eu. Muito prazer, Renata.","es":"Soy yo. Mucho gusto, Renata."},{"quien":"Renata","en":"O prazer é meu! Como foi o voo?","es":"¡El gusto es mío! ¿Cómo estuvo el vuelo?"},{"quien":"Daniel","en":"Foi tranquilo, obrigado. Cheguei ontem à noite.","es":"Tranquilo, gracias. Llegué anoche."},{"quien":"Renata","en":"E o hotel? Você gostou?","es":"¿Y el hotel? ¿Te gustó?"},{"quien":"Daniel","en":"Gostei muito. Fica pertinho daqui.","es":"Me gustó mucho. Está cerquita de aquí."},{"quien":"Renata","en":"Que bom! Depois da reunião vamos almoçar? Tem um restaurante por quilo ótimo aqui do lado.","es":"¡Qué bien! ¿Después de la junta vamos a comer? Hay un restaurante por kilo muy bueno aquí al lado."},{"quien":"Daniel","en":"Vamos, sim! Combinado.","es":"¡Claro que sí! Quedamos."}]},{"tipo":"practica","rotulo":"Decide en el viaje","preguntas":[{"p":"Renata pregunta <i>Como foi o voo?</i> Le contestas…","ops":["Foi ótimo, obrigado.","Estou ótimo o voo.","É tranquilo, obrigado."],"correcta":0,"explica":"Te pregunta en pasado (<i>foi</i>), así que contestas en pasado: <i>Foi…</i>"},{"p":"Necesitas la factura de la comida. Dices…","ops":["Pode me dar a fatura?","Pode me dar a nota fiscal?","Pode me dar a propina?"],"correcta":1,"explica":"En Brasil la factura de un consumo es la <b>nota fiscal</b>. Y recuerda: <i>propina</i> es soborno."},{"p":"En el restaurante por quilo quieres saber cuánto fue. Preguntas…","ops":["Quanto custou o quilo de você?","Quanto tempo demora?","Quanto deu?"],"correcta":2,"explica":"<i>Quanto deu?</i> es la forma natural de preguntar el total al pagar."},{"p":"Renata propone: <i>Amanhã às nove?</i> Para aceptar dices…","ops":["Combinado!","Combinação!","Está combinando."],"correcta":0}]},{"tipo":"relacionar","rotulo":"Relaciona la frase con su significado","voz":true,"pares":[["Como foi o voo?","¿Cómo estuvo el vuelo?"],["Cheguei ontem à noite.","Llegué anoche."],["Quanto deu?","¿Cuánto fue?"],["Pode me dar a nota fiscal?","¿Me da la factura?"],["Fica pertinho daqui.","Está cerquita de aquí."],["Combinado!","¡Quedamos!"]]},{"tipo":"escuchar","rotulo":"Escucha frases del viaje","frases":[{"en":"Como foi o voo?","pron":"kómu foi u vôu","es":"¿Cómo estuvo el vuelo?"},{"en":"Vamos almoçar depois da reunião?","pron":"vãmus aumosár depóis da jeuniãu","es":"¿Vamos a comer después de la junta?"},{"en":"Quanto deu?","pron":"kwãtu dêu","es":"¿Cuánto fue?"},{"en":"O táxi já chegou.","pron":"u táksi yá shegôu","es":"El taxi ya llegó."},{"en":"Boa viagem de volta!","pron":"bóa viáyẽi dji vóuta","es":"¡Buen viaje de regreso!"}]},{"tipo":"pronunciar","rotulo":"Resuelve el viaje en voz alta","frases":[{"en":"Eu tenho uma reserva em nome de Daniel Ortiz.","pron":"éu tẽñu úma jezérva ẽi nõmi dji daniéu ortís","es":"Tengo una reservación a nombre de Daniel Ortiz."},{"en":"Para a Avenida Paulista, por favor.","pron":"pára a avenída paulísta, pur favór","es":"A la Avenida Paulista, por favor."},{"en":"Cheguei ontem à noite.","pron":"shegêi õtẽi a nóichi","es":"Llegué anoche."},{"en":"A reunião foi muito boa.","pron":"a jeuniãu foi mũintu bóa","es":"La junta estuvo muy bien."},{"en":"Pode me dar a nota fiscal?","pron":"pódji mi dar a nóta fiskáu","es":"¿Me puede dar la factura?"}]},{"tipo":"completar","rotulo":"Completa el mensaje de Daniel a su jefe","voz":true,"items":[{"frase":"Eu ___ ontem à noite em São Paulo.","resp":["cheguei"],"es":"Llegué anoche a São Paulo."},{"frase":"A reunião ___ muito boa.","resp":["foi"],"es":"La junta estuvo muy bien."},{"frase":"Depois nós ___ num restaurante por quilo.","resp":["almoçamos","almocamos"],"es":"Después comimos en un restaurante por kilo."},{"frase":"Amanhã eu ___ voltar para Monterrey.","resp":["vou"],"es":"Mañana voy a regresar a Monterrey."}]},{"tipo":"ordenar","rotulo":"Arma las frases del viaje","voz":true,"items":[{"frase":"Eu trabalho numa empresa de Monterrey","es":"Trabajo en una empresa de Monterrey"},{"frase":"A reunião foi muito boa","es":"La junta estuvo muy bien"},{"frase":"Vamos almoçar depois da reunião?","es":"¿Vamos a comer después de la junta?"}]},{"tipo":"reflexion","rotulo":"Tu reporte del viaje","pregunta":"Escribe en portugués un mensaje de cinco o seis frases a Renata después del viaje: agradece la reunión, cuenta cuándo llegaste y qué te gustó de São Paulo, menciona la comida y propón el siguiente paso (una llamada o una visita).","ayuda":"Oi, Renata! Muito obrigado pela reunião. Eu cheguei… Eu gostei muito de… O almoço foi… Vamos marcar uma ligação na…? Abraço!"},{"tipo":"clave","items":["Pasado para contar el viaje: <i>cheguei, foi, gostei, almoçamos</i>.","Pagar y comprobar: <i>Quanto deu? Pode me dar a nota fiscal?</i>","Aceptar un plan: <i>Vamos, sim! Combinado!</i>"]}]},"q":{"c-portugues-a1-m1":[{"p":"Son las 10 de la mañana y saludas a un cliente. Dices…","ops":["Bons dias!","Bom dia!","Boa tarde!","Boa noite!"],"correcta":1},{"p":"Eres mujer y agradeces un favor. Dices…","ops":["Obrigado!","Obrigada!","Gracias!","Graça!"],"correcta":1},{"p":"Atiendes a un señor mayor en el hotel. ¿Qué pregunta es la adecuada?","ops":["E aí, beleza?","Como vai o senhor?","Tudo bem, cara?","Como vai usted?"],"correcta":1},{"p":"«Mucho gusto» se dice…","ops":["Muito gosto!","Muito prazer!","Muito bom!","Muito obrigado!"],"correcta":1},{"p":"«Vivo en Mérida», como lo diría un brasileño:","ops":["Moro em Mérida.","Vivo a Mérida.","Moro no Mérida.","Estou morando de Mérida."],"correcta":0},{"p":"Completa: <i>Vocês ___ de São Paulo?</i>","ops":["é","são","somos","estão de"],"correcta":1},{"p":"«Tengo hambre», en el portugués de Brasil más natural:","ops":["Sou com fome.","Estou com fome.","Tenho de fome.","Estou fome."],"correcta":1},{"p":"¿Cómo se pronuncia aproximadamente <i>noite</i>?","ops":["nói-te","nóichi","nóite con e clara","nóiti con t fuerte"],"correcta":1}],"c-portugues-a1-m2":[{"p":"Un cliente brasileño te dicta <i>nove, meia, meia, dois</i>. Anotas…","ops":["9332","9662","9222","9002"],"correcta":1},{"p":"«Dos horas» se dice…","ops":["dois horas","duas horas","dos horas","doas horas"],"correcta":1},{"p":"«Tengo 28 años» se dice…","ops":["Tenho vinte e oito anos.","Tenho vinte oito años.","Estou com vinte e oito anos.","Sou vinte e oito anos."],"correcta":0},{"p":"Tu compañero brasileño dice <i>Vou levar o carro na oficina.</i> Va a llevar el coche…","ops":["a la oficina","al taller","al estacionamiento","a la agencia"],"correcta":1},{"p":"Completa: <i>Eu sou ___ México.</i>","ops":["de o","do","da","no"],"correcta":1},{"p":"¿Cuál palabra es femenina en portugués?","ops":["leite","sal","viagem","sangue"],"correcta":2},{"p":"En un registro, tu apellido va en la casilla…","ops":["apelido","sobrenome","assinatura","endereço"],"correcta":1},{"p":"«¿Qué haces?» en portugués es…","ops":["Que faz você?","O que você faz?","Qué você faz?","Quem você faz?"],"correcta":1}],"c-portugues-a1-m3":[{"p":"Completa: <i>Vocês ___ português?</i>","ops":["falas","falam","falamos","falan"],"correcta":1},{"p":"<i>Eu acordo às seis</i> significa…","ops":["Me acuerdo a las seis.","Me despierto a las seis.","Quedo a las seis.","Me acuesto a las seis."],"correcta":1},{"p":"«Tomo el metro para ir al trabajo.»","ops":["Tomo o metrô para o trabalho.","Pego o metrô para o trabalho.","Colo o metrô para o trabalho.","Assisto o metrô para o trabalho."],"correcta":1},{"p":"¿Qué hora es? — <i>São quinze para as oito.</i>","ops":["8:15","7:45","8:45","7:15"],"correcta":1},{"p":"«La junta es a la una.»","ops":["A reunião é às uma.","A reunião é à uma.","A reunião é a la uma.","A reunião é as uma."],"correcta":1},{"p":"<i>quarta-feira</i> es…","ops":["martes","miércoles","jueves","el cuarto día del mes"],"correcta":1},{"p":"«Me gusta mucho Brasil.»","ops":["Me gosta muito o Brasil.","Eu gosto muito o Brasil.","Eu gosto muito do Brasil.","Eu gosto muito de o Brasil."],"correcta":2},{"p":"Un amigo brasileño prueba tu pozole y dice <i>Que esquisito!</i> Quiere decir que…","ops":["le encantó","le pareció raro","está muy caliente","quiere más"],"correcta":1}],"c-portugues-a1-m4":[{"p":"«¿Hay una farmacia cerca?», como se dice en la calle en Brasil:","ops":["Tem uma farmácia aqui perto?","Hay uma farmácia aqui perto?","Está uma farmácia aqui perto?","É uma farmácia aqui perto?"],"correcta":0},{"p":"<i>A rua é muito larga</i> significa que la calle es…","ops":["muy larga","muy ancha","muy peligrosa","muy bonita"],"correcta":1},{"p":"«Siga derecho y dé vuelta a la izquierda.»","ops":["Siga direita e vire à esquerda.","Siga reto e vire à esquerda.","Siga reto e vire a la esquerda.","Siga em frente e vire à direita."],"correcta":1},{"p":"«Voy al trabajo en camión.»","ops":["Vou ao trabalho de caminhão.","Vou ao trabalho de ônibus.","Vou ao trabalho a ônibus.","Vou ao trabalho em camião."],"correcta":1},{"p":"En un restaurante de mariscos ves <i>polvo grelhado</i>. Es…","ops":["pollo asado","pulpo a la parrilla","polvo de ajo","pescado frito"],"correcta":1},{"p":"<i>R$ 7,50</i> se lee…","ops":["sete reais e cinquenta","sete reales cincuenta","sete real e meio","setenta e cinco reais"],"correcta":0},{"p":"Pagaste con un billete de 50 reales. Esperas tu…","ops":["troca","troco","trocado de cartão","desconto"],"correcta":1},{"p":"«Mañana voy a comprar los boletos.»","ops":["Amanhã vou a comprar as passagens.","Amanhã vou comprar as passagens.","Amanhã compro a as passagens.","Amanhã vou comprando as passagens."],"correcta":1}],"c-portugues-a1-m5":[{"p":"Quieres una habitación en un hotel. Lo más cortés es…","ops":["Eu quero um quarto.","Eu queria um quarto, por favor.","Me dá um quarto.","Quarto, por favor, rápido."],"correcta":1},{"p":"Necesitas otra almohada. Pides un…","ops":["almofada","travesseiro","cobertor","copo"],"correcta":1},{"p":"Quieres dejarle propina al mesero. En portugués es…","ops":["propina","gorjeta","sobremesa","garrafa"],"correcta":1},{"p":"El mesero te ofrece <i>sobremesa</i>. Es…","ops":["la charla después de comer","el postre","el mantel","la cuenta"],"correcta":1},{"p":"«Ayer hablé con mi jefe.»","ops":["Ontem eu falé com o meu chefe.","Ontem eu falei com o meu chefe.","Ontem eu falou com o meu chefe.","Ontem eu fala com o meu chefe."],"correcta":1},{"p":"«El sábado fuimos a la playa.»","ops":["No sábado fuimos à praia.","No sábado fomos à praia.","No sábado vamos à praia.","No sábado foram à praia nós."],"correcta":1},{"p":"Tu colega brasileña dice <i>Estou grávida!</i> Te cuenta que…","ops":["está avergonzada","está embarazada","está enferma","está cansada"],"correcta":1},{"p":"Te invitan con <i>Topa?</i> y quieres ir. Respondes…","ops":["Topo!","Que pena!","Fica para a próxima.","Topou?"],"correcta":0}]}});
